-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Directives</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p><strong>Directives Standar:</strong></p>\n<p v-text=\"'1. Teks ini dirender via v-text'\"></p>\n<div v-html=\"'2. Teks dengan format <strong>HTML v-html</strong> (Warna <span style=\\'color:#42b883\\'>Hijau</span>)'\"></div>\n<p v-once style=\"color:#64748b; font-size:13px;\">3. Teks ini dirender v-once (nilai statis): {{ waktu }}</p>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            waktu: new Date().toLocaleTimeString()\n        };\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Directive <code>v-html</code> memungkinkan penyuntikan tag HTML kaya ke dalam DOM, sementara <code>v-once</code> mengunci nilai sejak pertama kali dipasang.</p>\n</div>"
      },
      "vue_v_bind": {
        "title": "Vue v-bind",
        "summary": "Mengikat atribut HTML secara dinamis dengan `v-bind` dan shortcut titik dua (`:href`, `:disabled`, `:src`, `:title`).",
        "content": "<p class=\"lead\">Atribut HTML biasa tidak dapat membaca interpolasi mustache <code>{{ }}</code>. Untuk mengikat data dinamis ke atribut HTML, gunakan directive <code>v-bind</code>.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Sintaks Lengkap: <code>v-bind:href=\"tautan\"</code>.</li><li>Shorthand Praktis: Cukup gunakan tanda titik dua <code>:href=\"tautan\"</code>, <code>:disabled=\"status\"</code>.</li><li>Atribut Boolean: Jika nilai bernilai <code>true</code> atribut ditambahkan, jika bernilai falsy (false/null/undefined) atribut otomatis dihilangkan dari elemen HTML.</li>\n    </ul>\n</div>",
