-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue v-bind</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Binding Atribut Dinamis:</p>\n<p>\n    <a :href=\"urlSitus\" target=\"_blank\" style=\"color:#42b883; font-weight:bold; text-decoration:none;\">\n        Kunjungi {{ labelSitus }} &raquo;\n    </a>\n</p>\n<button :disabled=\"tombolMati\" :title=\"keteranganTombol\">\n    {{ tombolMati ? 'Tombol Terkunci (Disabled)' : 'Tombol Aktif' }}\n</button>\n<div style=\"margin-top:12px;\">\n    <button @click=\"tombolMati = !tombolMati\" style=\"background:#0d2e5c; font-size:12px;\">\n        Toggle Status Disabled\n    </button>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            urlSitus: \"https://academy.skillance.cloud\",\n            labelSitus: \"Skillance Academy\",\n            tombolMati: false,\n            keteranganTombol: \"Tombol interaktif dengan atribut dinamis\"\n        };\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Atribut <code>:disabled=\"tombolMati\"</code> secara reaktif mengaktifkan atau menonaktifkan tombol HTML berdasarkan status boolean data.</p>\n</div>"
      },
      "vue_v_if": {
        "title": "Vue v-if",
        "summary": "Pencabangan kondisional tampilan: `v-if`, `v-else-if`, dan `v-else` untuk memasang atau mencopot elemen dari DOM.",
        "content": "<p class=\"lead\">Directive <code>v-if</code> digunakan untuk merender blok template secara kondisional. Blok hanya akan dipasang ke dalam pohon DOM jika ekspresi bernilai truthy.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Manipulasi DOM Riil: Elemen yang tidak memenuhi syarat benar-benar dihancurkan (unmounted) dari DOM.</li><li>Rantai Kondisi: Dapat dipasangkan berdampingan dengan <code>v-else-if</code> dan <code>v-else</code>.</li><li>Pengelompokan dengan <code>&lt;template&gt;</code>: Gunakan tag semu <code>&lt;template v-if=\"...\"&gt;</code> untuk membungkus banyak elemen tanpa menambahkan tag div pembungkus ekstra.</li>\n    </ul>\n</div>",
        "example_title": "Kondisional Rendering v-if / v-else",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue v-if</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"margin-bottom:12px;\">\n    <button @click=\"skor = 90\">Set Nilai A (90)</button>\n    <button @click=\"skor = 75\" style=\"margin-left:4px;\">Set Nilai B (75)</button>\n    <button @click=\"skor = 50\" style=\"margin-left:4px;\">Set Nilai C (50)</button>\n</div>\n<div style=\"padding:14px; border-radius:8px; margin-top:10px;\">\n    <p v-if=\"skor >= 85\" style=\"color:#16a34a; font-weight:bold; margin:0;\">\n        🎉 Selamat! Predikat: Nilai A (Sangat Memuaskan)\n    </p>\n    <p v-else-if=\"skor >= 70\" style=\"color:#ca8a04; font-weight:bold; margin:0;\">\n        👍 Bagus! Predikat: Nilai B (Kompeten)\n    </p>\n    <p v-else style=\"color:#dc2626; font-weight:bold; margin:0;\">\n        ⚠️ Perlu Latihan Lagi! Predikat: Nilai C (Remedial)\n    </p>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            skor: 90\n        };\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Ketika skor diubah, hanya elemen paragraf yang sesuai dengan kondisi logika yang dimasukkan ke dalam DOM, sementara elemen lain dihilangkan.</p>\n</div>"
      },
      "vue_v_show": {
        "title": "Vue v-show",
        "summary": "Mengontrol visibilitas elemen menggunakan CSS `display: none` vs `v-if`, serta perbandingan performa rendering.",
        "content": "<p class=\"lead\">Alternatif lain untuk menampilkan elemen secara kondisional adalah directive <code>v-show</code>.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Perilaku CSS: Elemen dengan <code>v-show</code> selalu dirender dan tetap ada di dalam DOM; Vue hanya mengubah properti CSS <code>display: none</code>.</li><li>Perbandingan dengan <code>v-if</code>: <code>v-if</code> memiliki biaya toggle lebih tinggi (karena create/destroy DOM), sedangkan <code>v-show</code> memiliki biaya render awal lebih tinggi.</li><li>Rekomendasi Pemilihan: Gunakan <code>v-show</code> untuk elemen yang sangat sering dibuka-tutup (seperti dropdown menu atau accordion dialog).</li>\n    </ul>\n</div>",
        "example_title": "Toggle Visibilitas dengan v-show",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue v-show</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <button @click=\"tampil = !tampil\">\n    {{ tampil ? 'Sembunyikan Panel Rahasia' : 'Tampilkan Panel Rahasia' }}\n</button>\n<div v-show=\"tampil\" style=\"background:#e0f2fe; padding:16px; border-radius:8px; margin-top:14px; border-left:4px solid #0284c7;\">\n    <strong>ℹ️ Panel Informasi Rahasia:</strong>\n    <p style=\"margin:6px 0 0 0; font-size:13px;\">\n        Elemen ini tetap ada di DOM, tetapi visibilitasnya diatur via CSS <code>display: none</code>.\n    </p>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            tampil: true\n        };\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Periksa Inspect Element di browser: saat disembunyikan, tag div masih ada di DOM dengan inline style <code>display: none</code>.</p>\n</div>"
      },
      "vue_v_for": {
        "title": "Vue v-for",
        "summary": "Perulangan list data array dan objek dengan `v-for`, parameter indeks, dan kewajiban atribut `:key` unik.",
        "content": "<p class=\"lead\">Directive <code>v-for</code> digunakan untuk merender daftar elemen berulang berdasarkan data array atau objek JavaScript.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Sintaks Iterator: <code>v-for=\"(item, index) in koleksi\"</code>.</li><li>Pentingnya Atribut <code>:key</code>: Selalu berikan key unik (seperti ID database) agar algoritma Virtual DOM Vue dapat melacak identitas tiap elemen secara optimal saat terjadi penambahan atau penghapusan.</li><li>Iterasi Rentang Angka: Dapat juga mengulang angka tetap seperti <code>v-for=\"n in 5\"</code>.</li>\n    </ul>\n</div>",
        "example_title": "Render Daftar Koleksi dengan v-for",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue v-for</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p><strong>Daftar Kursus Unggulan Skillance:</strong></p>\n<ul style=\"padding-left:18px; margin:0 0 15px 0;\">\n    <li v-for=\"(kursus, index) in daftarKursus\" :key=\"kursus.id\" style=\"margin-bottom:6px;\">\n        <span style=\"font-weight:bold;\">#{{ index + 1 }} {{ kursus.nama }}</span>\n        <span class=\"pill\" :style=\"{ background: kursus.warna, color: '#fff' }\">{{ kursus.kategori }}</span>\n    </li>\n</ul>\n<button @click=\"tambahKursus\">+ Tambah Kursus Baru</button>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            daftarKursus: [\n                { id: 1, nama: \"Vue.js 3 Frontend\", kategori: \"Frontend\", warna: \"#42b883\" },\n                { id: 2, nama: \"C++ High Performance\", kategori: \"Systems\", warna: \"#00599c\" },\n                { id: 3, nama: \"Python & AI Data\", kategori: \"AI & ML\", warna: \"#f59e0b\" }\n            ]\n        };\n    },\n    methods: {\n        tambahKursus() {\n            const idBaru = this.daftarKursus.length + 1;\n            this.daftarKursus.push({\n                id: idBaru,\n                nama: \"Fullstack Web Cloud #\" + idBaru,\n                kategori: \"Fullstack\",\n                warna: \"#6366f1\"\n            });\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Perulangan <code>v-for</code> membaca setiap objek kursus dan secara reaktif merender elemen baru saat tombol ditekan.</p>\n</div>"
      },
      "vue_events": {
        "title": "Vue Events",
        "summary": "Menangani event interaksi pengguna: Inline handlers, method handlers, dan objek event asli (`$event`).",
        "content": "<p class=\"lead\">Event handling di Vue memungkinkan aplikasi merespons aksi pengguna seperti klik mouse, ketukan keyboard, scroll, dan perubahan form.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Inline Handler: Menulis ekspresi JavaScript sederhana langsung di template: <code>@click=\"counter++\"</code>.</li><li>Method Handler: Memanggil method fungsi terpisah untuk logika yang lebih kompleks: <code>@click=\"prosesTransaksi\"</code>.</li><li>Akses Objek Native Event: Method handler secara otomatis menerima objek asli <code>event</code> dari browser.</li>\n    </ul>\n</div>",
        "example_title": "Membaca Objek Native Event Mouse",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Events</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#f8fafc; border:1px solid #e2e8f0; padding:18px; border-radius:8px; text-align:center;\">\n    <p style=\"margin:0 0 10px 0;\">Koordinat Kursor Mouse di Layar:</p>\n    <div style=\"background:#0d2e5c; color:#fff; padding:12px; border-radius:6px; cursor:crosshair;\" @mousemove=\"catatKoordinat\">\n        Gerakkan mouse di dalam kotak ini!<br>\n        <strong>X: {{ x }} px | Y: {{ y }} px</strong>\n    </div>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            x: 0,\n            y: 0\n        };\n    },\n    methods: {\n        catatKoordinat(event) {\n            this.x = event.offsetX;\n            this.y = event.offsetY;\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Fungsi <code>catatKoordinat(event)</code> menerima event objek mousemove dan mengekstrak koordinat piksel secara real-time.</p>\n</div>"
      },
      "vue_v_on": {
        "title": "Vue v-on",
        "summary": "Directive `v-on` dan shorthand `@`: Menghubungkan event klik, input, hover, dan melewatkan argumen fungsi kustom.",
        "content": "<p class=\"lead\">Directive <code>v-on</code> adalah jembatan utama untuk menghubungkan event listener DOM dengan logika JavaScript aplikasi Anda.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Sintaks Panjang: <code>v-on:click=\"namaMethod\"</code>.</li><li>Shorthand Populer: Cukup gunakan simbol at <code>@click=\"namaMethod\"</code>, <code>@submit=\"simpan\"</code>.</li><li>Passing Parameter Kustom: Anda dapat meneruskan argumen langsung seperti <code>@click=\"hapus(item.id)\"</code>.</li>\n    </ul>\n</div>",
        "example_title": "Penggunaan v-on dan Shorthand @",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue v-on</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"display:flex; gap:8px; flex-wrap:wrap;\">\n    <!-- Menggunakan sintaks v-on lengkap -->\n    <button v-on:click=\"salam('Pagi')\">Pagi</button>\n    <!-- Menggunakan shorthand @ -->\n    <button @click=\"salam('Siang')\">Siang</button>\n    <button @click=\"salam('Malam')\">Malam</button>\n</div>\n<div style=\"margin-top:14px; padding:10px; background:#f1f5f9; border-radius:6px;\">\n    Status: <strong>{{ pesanSalam }}</strong>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            pesanSalam: \"Pilih waktu di atas\"\n        };\n    },\n    methods: {\n        salam(waktu) {\n            this.pesanSalam = \"Selamat \" + waktu + \", Semangat belajar Vue.js!\";\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Shorthand <code>@click</code> lebih ringkas dan standar digunakan oleh seluruh komunitas developer Vue di dunia.</p>\n</div>"
      },
      "vue_methods": {
        "title": "Vue Methods",
        "summary": "Mendefinisikan kumpulan fungsi di dalam opsi `methods: { ... }`, konteks `this`, dan pemanggilan di template.",
        "content": "<p class=\"lead\">Properti <code>methods</code> adalah tempat mendeklarasikan fungsi-fungsi yang dapat dipanggil oleh template atau bagian skrip lainnya.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Binding Konteks <code>this</code>: Vue secara otomatis mengikat <code>this</code> ke instance komponen aktif sehingga Anda dapat mengakses data via <code>this.namaData</code>.</li><li>Hindari Arrow Function: Jangan mendefinisikan methods menggunakan arrow function (<code>() =&gt; {}</code>) karena akan merusak binding konteks <code>this</code>.</li><li>Eksekusi Tiap Render: Pemanggilan method di dalam template selalu dieksekusi ulang setiap kali komponen merender ulang.</li>\n    </ul>\n</div>",
        "example_title": "Kalkulasi Menggunakan Vue Methods",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Methods</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Kalkulator Luas Persegi Panjang:</p>\n<div style=\"display:flex; gap:8px; margin-bottom:10px;\">\n    <input type=\"number\" v-model.number=\"panjang\" placeholder=\"Panjang\" style=\"width:100px;\">\n    <span style=\"align-self:center;\">&times;</span>\n    <input type=\"number\" v-model.number=\"lebar\" placeholder=\"Lebar\" style=\"width:100px;\">\n</div>\n<div style=\"background:#e0f2fe; padding:12px; border-radius:6px;\">\n    Luas Dihitung via Method: <strong>{{ hitungLuas() }} cm&sup2;</strong>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            panjang: 12,\n            lebar: 8\n        };\n    },\n    methods: {\n        hitungLuas() {\n            return this.panjang * this.lebar;\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Method <code>hitungLuas()</code> membaca data <code>this.panjang</code> dan <code>this.lebar</code> lalu mengembalikan hasil perkalian langsung ke tampilan.</p>\n</div>"
      },
      "vue_event_modifiers": {
        "title": "Vue Event Modifiers",
        "summary": "Pengubah event praktis: `.prevent`, `.stop`, `.once`, `.self`, serta key modifiers keyboard (`.enter`, `.esc`).",
        "content": "<p class=\"lead\">Event Modifiers adalah postfix direktif yang dipisahkan oleh tanda titik (misal <code>@click.prevent</code>) untuk menyederhanakan pemanggilan rutin seperti <code>event.preventDefault()</code>.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li><code>.prevent</code>: Menghentikan aksi default browser (misal reload halaman saat submit form).</li><li><code>.stop</code>: Menghentikan perambatan event ke elemen induk (<code>event.stopPropagation()</code>).</li><li><code>.once</code>: Memastikan event handler hanya dipicu maksimal 1 kali.</li><li>Key Modifiers: <code>@keyup.enter</code>, <code>@keyup.esc</code>, <code>@keydown.tab</code> untuk menangani tombol keyboard spesifik.</li>\n    </ul>\n</div>",
        "example_title": "Penerapan Event & Key Modifiers",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Event Modifiers</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <!-- .prevent menghentikan reload submit form -->\n<form @submit.prevent=\"kirimForm\">\n    <p style=\"margin:0 0 8px 0; font-size:13px;\">Ketik dan tekan <strong>ENTER (.enter)</strong>:</p>\n    <input type=\"text\" v-model=\"teksInput\" @keyup.enter=\"kirimForm\" placeholder=\"Tulis catatan...\" style=\"width:100%;\">\n    <div style=\"margin-top:10px;\">\n        <button type=\"submit\">Kirim (.prevent)</button>\n        <!-- .once hanya menjalankan handler satu kali -->\n        <button type=\"button\" @click.once=\"hanyaSekali\" style=\"background:#6366f1; margin-left:6px;\">\n            Klik Sekali Saja (.once)\n        </button>\n    </div>\n</form>\n<p style=\"color:#0284c7; font-size:13px; margin-top:10px;\">{{ notifikasi }}</p>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            teksInput: \"\",\n            notifikasi: \"Menunggu aksi formulir...\"\n        };\n    },\n    methods: {\n        kirimForm() {\n            if (!this.teksInput) return;\n            this.notifikasi = \"Form berhasil dikirim tanpa reload: '\" + this.teksInput + \"'\";\n            this.teksInput = \"\";\n        },\n        hanyaSekali() {\n            alert(\"Tombol ini hanya aktif satu kali berkat modifier .once!\");\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Modifier <code>@submit.prevent</code> mencegah halaman me-refresh, dan <code>@keyup.enter</code> memicu pengiriman saat tombol Enter ditekan.</p>\n</div>"
      },
      "vue_forms": {
        "title": "Vue Forms",
        "summary": "Pengelolaan input form: Text, textarea, checkbox boolean/array, radio group, dan select option dropdown.",
        "content": "<p class=\"lead\">Vue mempermudah penanganan elemen formulir HTML dengan mengikat nilai input secara otomatis ke variabel reaktif.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Checkbox Tunggal: Mengikat ke tipe boolean (<code>true</code>/<code>false</code>).</li><li>Multiple Checkbox: Mengikat ke tipe data array untuk mengoleksi banyak pilihan sekaligus.</li><li>Radio Group & Select: Mengikat nilai atribut <code>value</code> yang sedang terpilih ke variabel tunggal.</li>\n    </ul>\n</div>",
        "example_title": "Integrasi Elemen Formulir Vue",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Forms</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"display:flex; flex-direction:column; gap:10px;\">\n    <label>\n        Pilih Tingkat Keahlian:\n        <select v-model=\"level\" style=\"width:100%; margin-top:4px;\">\n            <option value=\"Pemula\">Pemula (Beginner)</option>\n            <option value=\"Menengah\">Menengah (Intermediate)</option>\n            <option value=\"Mahir\">Mahir (Advanced)</option>\n        </select>\n    </label>\n\n    <label style=\"display:flex; align-items:center; gap:8px;\">\n        <input type=\"checkbox\" v-model=\"setuju\" style=\"width:auto; margin:0;\">\n        <span>Setuju dengan syarat dan ketentuan Skillance</span>\n    </label>\n</div>\n<div style=\"margin-top:14px; background:#f1f5f9; padding:10px; border-radius:6px; font-size:13px;\">\n    Level: <strong>{{ level }}</strong> | Persetujuan: <strong>{{ setuju ? 'Disetujui ✅' : 'Belum ❌' }}</strong>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            level: \"Pemula\",\n            setuju: false\n        };\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Vue mendeteksi tipe elemen HTML secara otomatis dan memperbarui state JavaScript saat pengguna memilih opsi dropdown atau mencentang checkbox.</p>\n</div>"
      },
      "vue_v_model": {
        "title": "Vue v-model",
        "summary": "Two-way data binding dua arah dengan `v-model`, serta modifier `.lazy`, `.number`, dan `.trim`.",
        "content": "<p class=\"lead\">Directive <code>v-model</code> menciptakan sinkronisasi dua arah (two-way binding) antara elemen formulir antarmuka dan data state JavaScript.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Sintaks Shorthand: <code>v-model</code> sebenarnya adalah kombinasi dari <code>:value</code> dan event <code>@input</code>.</li><li>Modifier <code>.trim</code>: Memangkas spasi kosong di awal dan akhir kalimat secara otomatis.</li><li>Modifier <code>.number</code>: Melakukan typecasting otomatis string input menjadi tipe number.</li><li>Modifier <code>.lazy</code>: Hanya menyinkronkan data saat event change (kehilangan fokus), bukan tiap ketikan tombol.</li>\n    </ul>\n</div>",
        "example_title": "Two-Way Binding dengan v-model",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue v-model</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p><strong>Two-Way Data Binding (2 Arah):</strong></p>\n<input type=\"text\" v-model.trim=\"namaMahasiswa\" placeholder=\"Ketik nama Anda di sini...\">\n<div style=\"margin-top:12px; background:#f8fafc; padding:12px; border-radius:8px; border:1px solid #cbd5e1;\">\n    Pratinjau Nama: <strong style=\"color:#42b883;\">{{ namaMahasiswa || '(Belum diisi)' }}</strong>\n    <br><small style=\"color:#64748b;\">Jumlah Karakter: {{ namaMahasiswa.length }}</small>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            namaMahasiswa: \"Rizky Pratama\"\n        };\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Setiap huruf yang Anda ketikkan langsung memperbarui variabel <code>namaMahasiswa</code> dan pratinjau teks secara instan.</p>\n</div>"
      },
      "vue_css_binding": {
        "title": "Vue CSS Binding",
        "summary": "Mengikat kelas CSS (`:class`) dan inline styles (`:style`) menggunakan objek dinamis dan array.",
        "content": "<p class=\"lead\">Vue menyediakan peningkatan khusus untuk binding atribut <code>class</code> dan <code>style</code> menggunakan objek dan array JavaScript.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Class Objek: <code>:class=\"{ active: isActive, 'text-danger': hasError }\"</code>.</li><li>Class Array: <code>:class=\"[kelasDasar, kelasTambahan]\"</code>.</li><li>Inline Style Objek: <code>:style=\"{ color: warnaTeks, fontSize: ukuran + 'px' }\"</code> dengan penamaan camelCase otomatis.</li>\n    </ul>\n</div>",
        "example_title": "Dynamic Class & Style Binding",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        .kotak-demo { padding: 16px; border-radius: 8px; transition: all 0.3s; background: #f1f5f9; border: 2px dashed #cbd5e1; text-align: center; }\n.kotak-demo.aktif { border-color: #42b883; border-style: solid; }\n.kotak-demo.gelap { background: #0f172a; color: #f8fafc; }\n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue CSS Binding</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div :class=\"['kotak-demo', { 'aktif': isAktif, 'gelap': isGelap }]\"\n     :style=\"{ fontSize: ukuranFont + 'px' }\">\n    Kotak Dinamis Berubah Gaya CSS!\n</div>\n<div style=\"margin-top:12px; display:flex; gap:8px;\">\n    <button @click=\"isAktif = !isAktif\">{{ isAktif ? 'Matikan Border Hijau' : 'Nyalakan Border Hijau' }}</button>\n    <button @click=\"isGelap = !isGelap\" style=\"background:#0d2e5c;\">Tema {{ isGelap ? 'Terang' : 'Gelap' }}</button>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            isAktif: true,\n            isGelap: false,\n            ukuranFont: 14\n        };\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Kelas CSS <code>aktif</code> dan <code>gelap</code> dipasang atau dicopot secara dinamis mengikuti status boolean data.</p>\n</div>"
      },
      "vue_computed_properties": {
        "title": "Vue Computed Properties",
        "summary": "Kalkulasi reaktif ter-cache dengan `computed: { ... }`: Perbedaan esensial dengan method biasa dalam hal efisiensi performa.",
        "content": "<p class=\"lead\">Computed Properties digunakan untuk data turunan yang memerlukan kalkulasi kompleks dari satu atau beberapa data state reaktif lainnya.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Sistem Caching Berbasis Dependensi: Computed property di-cache dan hanya dievaluasi ulang jika data dependensinya (seperti harga atau jumlah) berubah.</li><li>Perbedaan dengan Methods: Method biasa selalu dijalankan ulang setiap kali re-render terjadi, sedangkan computed property memanfaatkan nilai simpanan cache.</li><li>Getter dan Setter: Mendukung getter default dan opsional setter jika Anda ingin mengubah dependensi saat computed diubah.</li>\n    </ul>\n</div>",
        "example_title": "Kalkulasi Kasir dengan Computed Properties",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Computed Properties</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"display:flex; flex-direction:column; gap:8px;\">\n    <label>Harga Barang (Rp): <input type=\"number\" v-model.number=\"harga\"></label>\n    <label>Kuantitas (Qty): <input type=\"number\" v-model.number=\"jumlah\"></label>\n</div>\n<div style=\"margin-top:14px; background:#e0f2fe; padding:14px; border-radius:8px;\">\n    <p style=\"margin:0 0 6px 0;\">Subtotal: Rp {{ subtotal.toLocaleString('id-ID') }}</p>\n    <p style=\"margin:0; font-weight:bold; color:#0284c7; font-size:16px;\">\n        Total + PPN (11%): Rp {{ totalTermasukPPN.toLocaleString('id-ID') }}\n    </p>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            harga: 50000,\n            jumlah: 2\n        };\n    },\n    computed: {\n        subtotal() {\n            return this.harga * this.jumlah;\n        },\n        totalTermasukPPN() {\n            return this.subtotal * 1.11;\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Nilai <code>subtotal</code> dan <code>totalTermasukPPN</code> otomatis diperbarui secara instan saat harga atau jumlah diubah, dengan caching optimal.</p>\n</div>"
      },
      "vue_watchers": {
        "title": "Vue Watchers",
        "summary": "Memantau perubahan data dengan opsi `watch: { ... }`, menangani operasi asinkron (AJAX fetch), dan deep watchers.",
        "content": "<p class=\"lead\">Sementara computed property cocok untuk kalkulasi sinkron, Watcher digunakan untuk menjalankan efek samping (side effects) saat suatu data berubah.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Kapan Menggunakan Watcher: Melakukan request API (HTTP fetch), manipulasi audio/video, atau menyimpan state ke localStorage.</li><li>Parameter Nilai Baru & Lama: Method watcher menerima dua argumen: <code>(newVal, oldVal)</code>.</li><li>Opsi <code>deep</code> & <code>immediate</code>: Memantau mutasi dalam objek bersarang (deep) atau memicu watcher langsung saat komponen pertama kali dimuat (immediate).</li>\n    </ul>\n</div>",
        "example_title": "Memantau Perubahan Input dengan Watchers",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Watchers</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Pencarian Real-Time (Simulasi API):</p>\n<input type=\"text\" v-model=\"kueriPencarian\" placeholder=\"Ketik kata kunci...\">\n<div style=\"margin-top:12px; font-size:13px; color:#64748b;\">\n    Status Watcher: <strong>{{ statusPencarian }}</strong>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            kueriPencarian: \"\",\n            statusPencarian: \"Menunggu masukan ketikan...\"\n        };\n    },\n    watch: {\n        kueriPencarian(nilaiBaru, nilaiLama) {\n            this.statusPencarian = \"Mendeteksi perubahan dari '\" + nilaiLama + \"' ke '\" + nilaiBaru + \"'... Mencari data...\";\n            // Simulasi panggilan AJAX asinkron\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Fungsi <code>kueriPencarian</code> di dalam objek watch memantau perubahan teks dan menjalankan logika efek samping secara otomatis.</p>\n</div>"
      },
      "vue_templates": {
        "title": "Vue Templates",
        "summary": "Sintaks template berbasis HTML: Interpolasi Mustache `{{ }}`, ekspresi JavaScript tunggal, dan pembatasan sintaks.",
        "content": "<p class=\"lead\">Vue menggunakan sintaks template berbasis HTML valid yang dapat diurai oleh semua browser dan parser standar.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Mustache Tag <code>{{ }}</code>: Menyisipkan data teks biasa secara reaktif.</li><li>Hanya Ekspresi Tunggal: Di dalam kurung kurawal, Anda dapat menulis satu ekspresi JavaScript (seperti ternary atau method string), tetapi bukan statement (seperti <code>var a = 1</code> atau <code>if</code> blok).</li><li>Keamanan XSS Otomatis: Mustache selalu meng-escape karakter HTML khusus untuk mencegah serangan injeksi kode berbahaya.</li>\n    </ul>\n</div>",
        "example_title": "Ekspresi Interpolasi dalam Template Vue",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Templates</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p><strong>Ekspresi JavaScript dalam Template:</strong></p>\n<div style=\"background:#f1f5f9; padding:12px; border-radius:6px; font-size:13px;\">\n    1. Operasi Matematika: {{ 10 + 25 * 2 }}<br>\n    2. Manipulasi String: {{ nama.toUpperCase() }}<br>\n    3. Operator Ternary: {{ statusAktif ? 'AKUN AKTIF 🟢' : 'NON-AKTIF 🔴' }}\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            nama: \"Skillance Academy\",\n            statusAktif: true\n        };\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Di dalam tanda <code>{{ }}</code>, ekspresi JavaScript dievaluasi secara dinamis dalam lingkup data instance komponen.</p>\n</div>"
      }
    },
    "Scaling Up": {
      "vue_scale_up": {
        "title": "Vue Why, How and Setup",
        "summary": "Meningkatkan skala aplikasi: Beralih dari CDN ke ekosistem Vite, Node.js/npm, dan struktur Single Page Application (SPA).",
        "content": "<p class=\"lead\">Ketika aplikasi Anda bertambah besar, memuat Vue via CDN di file HTML tunggal tidak lagi efisien. Diperlukan toolchain modern untuk modularitas dan performa maksimal.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Vite Build Tool: Toolchain generasi baru berbasis ES Modules yang menawarkan server lokal berkecepatan instan dan Hot Module Replacement (HMR).</li><li>Single Page Application (SPA): Aplikasi hanya memuat 1 halaman HTML di awal dan merender tampilan secara dinamis di browser pengguna.</li><li>Perintah Resmi: <code>npm create vue@latest</code> untuk scaffolding proyek lengkap dengan TypeScript, Vue Router, Pinia, dan Vitest.</li>\n    </ul>\n</div>",
        "example_title": "Setup Proyek Vite Vue 3",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Setup & Scaling Up</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#0f172a; color:#f8fafc; padding:16px; border-radius:8px; font-family:monospace; font-size:13px;\">\n    <div style=\"color:#64748b; margin-bottom:6px;\"># Inisialisasi Proyek Modern dengan Vite:</div>\n    <div style=\"color:#42b883;\">$ npm create vue@latest</div>\n    <div style=\"color:#38bdf8;\">$ cd skillance-vue-app</div>\n    <div style=\"color:#38bdf8;\">$ npm install</div>\n    <div style=\"color:#4ade80;\">$ npm run dev</div>\n</div>\n<p style=\"margin-top:12px; font-size:13px; color:#64748b;\">\n    Status: Siap mengembangkan Single Page Application (SPA) modular dengan Hot Module Replacement (HMR).\n</p>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Toolchain Vite membundel aset web secara modular dan mengompilasi Single File Components (.vue) menjadi JavaScript biner optimal.</p>\n</div>"
      },
      "vue_sfc_first": {
        "title": "Vue First SFC Page",
        "summary": "Membuat komponen file tunggal (`.vue`): 3 blok utama `<template>`, `<script>`, dan `<style scoped>`.",
        "content": "<p class=\"lead\">Single File Component (SFC) dengan ekstensi <code>.vue</code> adalah standar industri penulisan komponen Vue yang menyatukan HTML, JS, dan CSS dalam satu berkas terpadu.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Blok <code>&lt;template&gt;</code>: Berisi struktur tampilan antarmuka HTML komponen.</li><li>Blok <code>&lt;script&gt;</code>: Mengelola logika reaktivitas, methods, computed properties, dan imports.</li><li>Blok <code>&lt;style scoped&gt;</code>: Menampung gaya visual CSS yang hanya berlaku khusus untuk elemen di dalam komponen tersebut.</li>\n    </ul>\n</div>",
        "example_title": "Struktur Berkas SFC (.vue)",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue First SFC Page</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#1e293b; color:#f8fafc; padding:14px; border-radius:8px; font-family:monospace; font-size:13px;\">\n<span style=\"color:#94a3b8;\">&lt;!-- App.vue (Single File Component) --&gt;</span><br>\n<span style=\"color:#f472b6;\">&lt;template&gt;</span><br>\n&nbsp;&nbsp;&lt;h1&gt;{{ judul }}&lt;/h1&gt;<br>\n<span style=\"color:#f472b6;\">&lt;/template&gt;</span><br><br>\n<span style=\"color:#38bdf8;\">&lt;script&gt;</span><br>\nexport default {<br>\n&nbsp;&nbsp;data() { return { judul: 'Halaman SFC Pertama' }; }<br>\n}<br>\n<span style=\"color:#38bdf8;\">&lt;/script&gt;</span><br><br>\n<span style=\"color:#4ade80;\">&lt;style scoped&gt;</span><br>\nh1 { color: #42b883; }<br>\n<span style=\"color:#4ade80;\">&lt;/style&gt;</span>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Penyatuan 3 blok ini ke dalam berkas SFC meningkatkan kohesi kode dan mempermudah pemeliharaan komponen mandiri.</p>\n</div>"
      },
      "vue_components": {
        "title": "Vue Components",
        "summary": "Membangun blok antarmuka modular: Pembuatan komponen, registrasi global via `app.component()`, dan reusabilitas UI.",
        "content": "<p class=\"lead\">Komponen adalah blok pembangun independen yang dapat digunakan kembali berkali-kali di berbagai bagian halaman web.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Modularitas: Memecah aplikasi antarmuka besar menjadi bagian-bagian kecil (seperti Navbar, Card, Footer).</li><li>Isolasi State: Setiap instance komponen memiliki salinan datanya sendiri yang tidak saling bentrok.</li><li>Komponen Global: Didaftarkan dengan <code>app.component('nama', {...})</code> dan dapat langsung dipanggil di template manapun.</li>\n    </ul>\n</div>",
        "example_title": "Registrasi & Pemanggilan Komponen",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Components</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p><strong>Komponen Berulang (Reusable UI):</strong></p>\n<kartu-profil nama=\"Andi Pratama\" peran=\"Frontend Developer\"></kartu-profil>\n<kartu-profil nama=\"Siti Rahma\" peran=\"UI/UX Designer\"></kartu-profil>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        const app = createApp({});\n\napp.component('kartu-profil', {\n    props: ['nama', 'peran'],\n    template: `\n        <div style=\"background:#f1f5f9; padding:12px; border-radius:8px; margin-bottom:8px; border-left:4px solid #42b883;\">\n            <strong style=\"color:#0d2e5c;\">{{ nama }}</strong>\n            <div style=\"font-size:12px; color:#64748b;\">Peran: {{ peran }}</div>\n        </div>\n    `\n});\n\napp.mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Komponen kustom <code>&lt;kartu-profil&gt;</code> diinstansiasi dua kali dengan data yang berbeda secara bersih dan rapi.</p>\n</div>"
      },
      "vue_props": {
        "title": "Vue Props",
        "summary": "Komunikasi parent-to-child: Mendefinisikan props, validasi tipe data (type, required, default), dan aliran data satu arah (one-way data flow).",
        "content": "<p class=\"lead\">Props adalah atribut kustom yang didaftarkan pada suatu komponen untuk menerima data yang dikirimkan oleh komponen induk (parent).</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>One-Way Data Flow: Data hanya mengalir ke bawah dari parent ke child. Child dilarang memodifikasi prop secara langsung.</li><li>Validasi Props: Tentukan tipe data (<code>String</code>, <code>Number</code>, <code>Boolean</code>, <code>Array</code>, <code>Object</code>) dan nilai default.</li><li>Dynamic Binding: Gunakan shortcut titik dua <code>:prop=\"variabel\"</code> agar prop dievaluasi sebagai ekspresi JavaScript.</li>\n    </ul>\n</div>",
        "example_title": "Validasi Props pada Komponen Child",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Props</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Meneruskan Data via Props:</p>\n<lencana-skor :skor=\"95\" label=\"Algoritma\"></lencana-skor>\n<lencana-skor :skor=\"80\" label=\"Database SQL\"></lencana-skor>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        const app = createApp({});\n\napp.component('lencana-skor', {\n    props: {\n        skor: { type: Number, required: true },\n        label: { type: String, default: \"Materi\" }\n    },\n    template: `\n        <div style=\"display:flex; justify-content:space-between; align-items:center; background:#e0f2fe; padding:10px 14px; border-radius:6px; margin-bottom:6px;\">\n            <span style=\"font-weight:600;\">{{ label }}</span>\n            <span style=\"background:#0284c7; color:#fff; padding:2px 10px; border-radius:12px; font-size:12px; font-weight:bold;\">\n                {{ skor }} Poin\n            </span>\n        </div>\n    `\n});\n\napp.mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Komponen anak menerima nilai prop <code>skor</code> dan <code>label</code> dengan validasi tipe data yang ketat.</p>\n</div>"
      },
      "vue_v_for_comp": {
        "title": "Vue v-for Components",
        "summary": "Menggabungkan perulangan `v-for` dengan komponen kustom, dynamic props passing, dan keharusan atribut unik `:key`.",
        "content": "<p class=\"lead\">Saat merender sekumpulan objek data menjadi komponen-komponen terpisah, Anda mengombinasikan directive <code>v-for</code> dengan tag komponen anak.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Explicit Prop Passing: Data tidak otomatis masuk ke komponen anak; Anda harus meneruskannya secara eksplisit via props seperti <code>:item=\"item\"</code>.</li><li>Wajib Atribut <code>:key</code>: Atribut key wajib berada di tag komponen terluar untuk menjaga integritas status komponen saat daftar dimutasi.</li>\n    </ul>\n</div>",
        "example_title": "Perulangan List Komponen dengan v-for",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue v-for Components</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Merender Koleksi Komponen:</p>\n<item-tugas v-for=\"t in daftarTugas\" :key=\"t.id\" :tugas=\"t\"></item-tugas>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        const app = createApp({\n    data() {\n        return {\n            daftarTugas: [\n                { id: 1, judul: \"Pelajari Props Vue 3\", selesai: true },\n                { id: 2, judul: \"Latihan Event $emit\", selesai: false },\n                { id: 3, judul: \"Bangun Proyek Portofolio\", selesai: false }\n            ]\n        };\n    }\n});\n\napp.component('item-tugas', {\n    props: ['tugas'],\n    template: `\n        <div style=\"display:flex; align-items:center; gap:8px; padding:8px 0; border-bottom:1px solid #f1f5f9;\">\n            <span>{{ tugas.selesai ? '✅' : '⏳' }}</span>\n            <span :style=\"{ textDecoration: tugas.selesai ? 'line-through' : 'none', color: tugas.selesai ? '#94a3b8' : '#1e293b' }\">\n                {{ tugas.judul }}\n            </span>\n        </div>\n    `\n});\n\napp.mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Setiap objek dalam array <code>daftarTugas</code> diteruskan ke komponen anak <code>item-tugas</code> secara dinamis.</p>\n</div>"
      },
      "vue_emit": {
        "title": "Vue $emit()",
        "summary": "Komunikasi child-to-parent: Memicu event kustom dengan `$emit()`, mengirim payload data, dan deklarasi opsi `emits: [...]`.",
        "content": "<p class=\"lead\">Ketika komponen anak perlu memberi tahu komponen induk bahwa sesuatu telah terjadi, komponen anak memicu event kustom menggunakan <code>$emit()</code>.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Memicu Event: <code>this.$emit('nama-event', payload)</code>.</li><li>Mendengarkan di Parent: Komponen induk mendengarkan event tersebut seperti event standar: <code>@nama-event=\"handler\"</code>.</li><li>Opsi <code>emits</code>: Mendokumentasikan dan memvalidasi seluruh event kustom yang dipancarkan oleh komponen anak.</li>\n    </ul>\n</div>",
        "example_title": "Komunikasi Child-to-Parent via $emit",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue $emit()</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Ukuran Font Teks: <strong>{{ ukuranTeks }}px</strong></p>\n<div :style=\"{ fontSize: ukuranTeks + 'px', marginBottom: '14px', background: '#f8fafc', padding: '10px' }\">\n    Skillance Academy Indonesia\n</div>\n<!-- Komponen child memicu event @ubah-ukuran -->\n<kontrol-font @ubah-ukuran=\"perbaruiUkuran\"></kontrol-font>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        const app = createApp({\n    data() {\n        return {\n            ukuranTeks: 15\n        };\n    },\n    methods: {\n        perbaruiUkuran(delta) {\n            this.ukuranTeks += delta;\n        }\n    }\n});\n\napp.component('kontrol-font', {\n    emits: ['ubah-ukuran'],\n    template: `\n        <div style=\"display:flex; gap:6px;\">\n            <button @click=\"$emit('ubah-ukuran', 2)\">+ Perbesar Teks</button>\n            <button @click=\"$emit('ubah-ukuran', -2)\" style=\"background:#64748b;\">- Perkecil Teks</button>\n        </div>\n    `\n});\n\napp.mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Komponen anak memancarkan event <code>ubah-ukuran</code> membawa angka delta yang kemudian ditangkap oleh method parent.</p>\n</div>"
      },
      "vue_fallthru_attr": {
        "title": "Vue Fallthrough Attributes",
        "summary": "Atribut fallthrough: Bagaimana `class`, `style`, `id`, dan event listener diteruskan otomatis ke elemen root komponen anak.",
        "content": "<p class=\"lead\">Fallthrough Attribute adalah atribut atau event listener yang dilewatkan ke komponen anak tetapi tidak dideklarasikan secara eksplisit dalam props atau emits.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Pewarisan Otomatis: Secara default, jika komponen hanya memiliki 1 elemen root, atribut luar akan digabungkan ke elemen root tersebut.</li><li>Penggabungan Cerdas: Kelas (<code>class</code>) dan gaya (<code>style</code>) dari luar digabung (merged) dengan kelas/style yang ada di dalam root child.</li><li>Nonaktifkan Pewarisan: Opsi <code>inheritAttrs: false</code> dan akses manual via <code>$attrs</code>.</li>\n    </ul>\n</div>",
        "example_title": "Penerusan Atribut Fallthrough Otomatis",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Fallthrough Attributes</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Fallthrough Attributes Demo:</p>\n<!-- class, style, dan id diteruskan otomatis ke root elemen child -->\n<tombol-kustom class=\"btn-khusus\" title=\"Tombol dengan Fallthrough\">\n    Klik Saya\n</tombol-kustom>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        const app = createApp({});\n\napp.component('tombol-kustom', {\n    template: `\n        <button style=\"border: 2px solid #0d2e5c; padding: 10px 20px;\">\n            <slot></slot>\n        </button>\n    `\n});\n\napp.mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Atribut <code>class=\"btn-khusus\"</code> dan <code>title</code> otomatis diwariskan ke tag <code>&lt;button&gt;</code> di dalam komponen anak.</p>\n</div>"
      },
      "vue_scoped_styling": {
        "title": "Vue Scoped Styling",
        "summary": "Enkapsulasi CSS dengan `<style scoped>`: Bagaimana PostCSS menambahkan atribut penanda unik untuk mencegah kebocoran gaya visual.",
        "content": "<p class=\"lead\">Dengan menambahkan atribut <code>scoped</code> pada tag <code>&lt;style&gt;</code>, aturan CSS hanya akan diterapkan pada elemen di dalam komponen tersebut.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Atribut Data Unik: Kompiler PostCSS otomatis menambahkan atribut penanda acak seperti <code>[data-v-f3f3eg9]</code> ke elemen DOM dan selektor CSS.</li><li>Mencegah Tabrakan Gaya (Style Leaks): Nama kelas umum seperti <code>.button</code> atau <code>.title</code> tidak akan saling menimpa antar komponen berbeda.</li><li>Deep Selector: Gunakan selektor pseudo <code>:deep(.elemen-anak)</code> untuk menargetkan elemen anak secara terarah.</li>\n    </ul>\n</div>",
        "example_title": "Konsep CSS Scoped dalam Berkas SFC",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Scoped Styling</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#1e293b; color:#f8fafc; padding:14px; border-radius:8px; font-family:monospace; font-size:13px;\">\n<span style=\"color:#94a3b8;\">&lt;!-- Tombol.vue --&gt;</span><br>\n&lt;template&gt;<br>\n&nbsp;&nbsp;&lt;button class=\"btn\"&gt;Tombol Terisolasi&lt;/button&gt;<br>\n&lt;/template&gt;<br><br>\n<span style=\"color:#4ade80;\">&lt;style scoped&gt;</span><br>\n.btn {<br>\n&nbsp;&nbsp;background: #42b883;<br>\n&nbsp;&nbsp;/* Hanya berlaku untuk komponen ini via atribut [data-v-xxxxxx] */<br>\n}<br>\n<span style=\"color:#4ade80;\">&lt;/style&gt;</span>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Fitur <code>scoped</code> menjamin setiap komponen memiliki gaya visual yang terenkapsulasi penuh tanpa mengotori CSS global.</p>\n</div>"
      },
      "vue_local_components": {
        "title": "Vue Local Components",
        "summary": "Registrasi komponen lokal via opsi `components: { ... }`: Meningkatkan efisiensi bundle size melalui tree-shaking.",
        "content": "<p class=\"lead\">Berbeda dengan komponen global yang selalu disertakan dalam bundle akhir, komponen lokal hanya diimpor dan didaftarkan saat dibutuhkan.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Tree-Shaking: Komponen lokal yang tidak terpakai akan otomatis dipangkas oleh bundler Vite sehingga ukuran berkas akhir lebih kecil.</li><li>Keterlacakan Dependensi: Mempermudah melacak dari mana suatu komponen berasal langsung dari baris <code>import</code>.</li><li>Gaya Penulisan: Di Composition API <code>&lt;script setup&gt;</code>, komponen yang di-import langsung siap digunakan tanpa perlu opsi <code>components</code>.</li>\n    </ul>\n</div>",
        "example_title": "Registrasi Komponen Lokal SFC",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Local Components</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#1e293b; color:#f8fafc; padding:14px; border-radius:8px; font-family:monospace; font-size:13px;\">\n<span style=\"color:#38bdf8;\">&lt;script&gt;</span><br>\nimport HeaderNav from './HeaderNav.vue';<br>\nimport FooterApp from './FooterApp.vue';<br><br>\nexport default {<br>\n&nbsp;&nbsp;components: {<br>\n&nbsp;&nbsp;&nbsp;&nbsp;HeaderNav,<br>\n&nbsp;&nbsp;&nbsp;&nbsp;FooterApp<br>\n&nbsp;&nbsp;}<br>\n}<br>\n<span style=\"color:#38bdf8;\">&lt;/script&gt;</span>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Registrasi lokal mengisolasi ketersediaan komponen dan memangkas ukuran biner aplikasi yang diunduh oleh pengguna.</p>\n</div>"
      },
      "vue_slots": {
        "title": "Vue Slots",
        "summary": "Distribusi konten template dengan elemen `<slot></slot>`: Membuat komponen wadah (container) fleksibel dengan fallback default.",
        "content": "<p class=\"lead\">Slot adalah outlet penampung konten di dalam komponen anak yang memungkinkan komponen induk menyuntikkan template HTML kustom.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Elemen <code>&lt;slot&gt;</code>: Bertindak sebagai placeholder tempat konten dari parent akan disisipkan.</li><li>Konten Fallback: Anda dapat menuliskan teks atau elemen di dalam tag slot anak yang otomatis tampil jika parent tidak memberikan konten apapun.</li><li>Kegunaan: Membangun komponen reusable seperti Card, Modal Dialog, Layout wrapper, dan Button ber-ikon.</li>\n    </ul>\n</div>",
        "example_title": "Penerapan Slot Dasar pada Komponen Card",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Slots</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Distribusi Konten dengan Slot:</p>\n<kartu-info>\n    <h4 style=\"margin:0 0 6px 0; color:#0d2e5c;\">Pengumuman Penting!</h4>\n    <p style=\"margin:0; font-size:13px; color:#475569;\">\n        Ujian sertifikasi Vue.js akan diselenggarakan akhir pekan ini di Skillance Academy.\n    </p>\n</kartu-info>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        const app = createApp({});\n\napp.component('kartu-info', {\n    template: `\n        <div style=\"border: 1px solid #cbd5e1; border-radius: 8px; padding: 16px; background: #fff; box-shadow: 0 2px 6px rgba(0,0,0,0.04);\">\n            <slot>Konten default jika parent tidak mengirim apapun.</slot>\n        </div>\n    `\n});\n\napp.mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Komponen induk menyuntikkan judul h4 dan paragraf ke dalam outlet <code>&lt;slot&gt;</code> di dalam komponen anak <code>kartu-info</code>.</p>\n</div>"
      },
      "vue_v_slot": {
        "title": "Vue v-slot",
        "summary": "Named slots untuk komponen multi-outlet: Menggunakan `v-slot:nama` dan shorthand `#nama` pada tag `<template>`.",
        "content": "<p class=\"lead\">Ketika suatu komponen memerlukan lebih dari satu slot outlet (misal header, badan utama, dan footer), Anda menggunakan Named Slots.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Atribut Name: <code>&lt;slot name=\"header\"&gt;</code> pada komponen anak.</li><li>Directive <code>v-slot</code>: Diletakkan pada tag <code>&lt;template v-slot:header&gt;</code> pada sisi parent.</li><li>Shorthand Karakter Pagar (<code>#</code>): Menyingkat <code>v-slot:header</code> menjadi <code>#header</code> dan <code>#footer</code>.</li>\n    </ul>\n</div>",
        "example_title": "Penerapan Named Slots (#header, #footer)",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue v-slot</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Named Slots dengan Shorthand #:</p>\n<panel-dialog>\n    <template #header>\n        <h4 style=\"margin:0; color:#42b883;\">Judul Dialog Modal</h4>\n    </template>\n    \n    <template #default>\n        <p style=\"margin:0; font-size:13px;\">Apakah Anda yakin ingin menyimpan perubahan data kursus ini?</p>\n    </template>\n    \n    <template #footer>\n        <button style=\"font-size:12px;\">Ya, Simpan</button>\n    </template>\n</panel-dialog>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        const app = createApp({});\n\napp.component('panel-dialog', {\n    template: `\n        <div style=\"border:1px solid #e2e8f0; border-radius:8px; overflow:hidden;\">\n            <div style=\"background:#f1f5f9; padding:10px 14px; border-bottom:1px solid #e2e8f0;\">\n                <slot name=\"header\"></slot>\n            </div>\n            <div style=\"padding:14px;\">\n                <slot></slot>\n            </div>\n            <div style=\"background:#f8fafc; padding:10px 14px; border-top:1px solid #e2e8f0; text-align:right;\">\n                <slot name=\"footer\"></slot>\n            </div>\n        </div>\n    `\n});\n\napp.mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Parent mendistribusikan elemen spesifik ke slot <code>#header</code>, <code>#default</code>, dan <code>#footer</code> secara presisi.</p>\n</div>"
      },
      "vue_scoped_slots": {
        "title": "Vue Scoped Slots",
        "summary": "Mengirimkan data dari anak kembali ke slot parent menggunakan Scoped Slots dan destructuring objek.",
        "content": "<p class=\"lead\">Scoped Slots memungkinkan komponen anak meneruskan data internalnya ke template slot milik parent sehingga parent memiliki kontrol penuh atas cara rendering data tersebut.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Child Menyerahkan Data: Menambahkan atribut props pada slot: <code>&lt;slot :data=\"dataChild\"&gt;</code>.</li><li>Parent Menerima Data: Mengakses via <code>#default=\"slotProps\"</code> atau destructuring <code>#default=\"{ data }\"</code>.</li><li>Pola Desain Renderless Components: Memisahkan logika manipulasi data sepenuhnya dari tata letak visual.</li>\n    </ul>\n</div>",
        "example_title": "Implementasi Scoped Slot Data Passing",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Scoped Slots</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Scoped Slot (Meneruskan Data Child ke Parent):</p>\n<daftar-pengguna>\n    <template #item=\"slotProps\">\n        <span style=\"color:#0284c7; font-weight:bold;\">{{ slotProps.user.nama }}</span>\n        <span style=\"font-size:12px; color:#64748b;\"> ({{ slotProps.user.role }})</span>\n    </template>\n</daftar-pengguna>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        const app = createApp({});\n\napp.component('daftar-pengguna', {\n    data() {\n        return {\n            users: [\n                { id: 1, nama: \"Budi Santoso\", role: \"Admin\" },\n                { id: 2, nama: \"Citra Dewi\", role: \"Mentor\" }\n            ]\n        };\n    },\n    template: `\n        <ul style=\"padding-left:18px; margin:0;\">\n            <li v-for=\"u in users\" :key=\"u.id\" style=\"margin-bottom:6px;\">\n                <!-- Mengirim data u ke parent via slot props -->\n                <slot name=\"item\" :user=\"u\"></slot>\n            </li>\n        </ul>\n    `\n});\n\napp.mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Komponen anak mengelola array data <code>users</code>, sedangkan komponen induk menentukan bagaimana setiap baris nama dan peran dirender.</p>\n</div>"
      },
      "vue_dynamic_components": {
        "title": "Vue Dynamic Components",
        "summary": "Berganti komponen secara dinamis dengan `<component :is=\"...\">` dan menyimpan state dengan `<KeepAlive>`.",
        "content": "<p class=\"lead\">Elemen semu <code>&lt;component&gt;</code> memungkinkan Anda beralih antar komponen berbeda secara dinamis berdasarkan nilai variabel reaktif.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Atribut <code>:is</code>: Menampung nama string komponen terdaftar atau objek komponen aktual.</li><li>Tag Pembungkus <code>&lt;KeepAlive&gt;</code>: Mencegah komponen dihancurkan (unmounted) saat berpindah tab sehingga input formulir atau posisi scroll tetap terjaga di memori cache.</li><li>Lifecycle Khusus: Komponen di dalam KeepAlive memiliki hook tambahan <code>activated</code> dan <code>deactivated</code>.</li>\n    </ul>\n</div>",
        "example_title": "Sistem Tab Dinamis dengan KeepAlive",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Dynamic Components</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"display:flex; gap:6px; margin-bottom:12px;\">\n    <button @click=\"tabAktif = 'TabMateri'\">Materi</button>\n    <button @click=\"tabAktif = 'TabDiskusi'\" style=\"background:#6366f1;\">Diskusi</button>\n</div>\n<!-- KeepAlive menjaga state tab saat berganti -->\n<keep-alive>\n    <component :is=\"tabAktif\"></component>\n</keep-alive>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        const app = createApp({\n    data() {\n        return {\n            tabAktif: 'TabMateri'\n        };\n    }\n});\n\napp.component('TabMateri', {\n    template: '<div style=\"background:#e0f2fe; padding:12px; border-radius:6px;\">📖 Konten Modul Pembelajaran Vue 3</div>'\n});\n\napp.component('TabDiskusi', {\n    template: '<div style=\"background:#fef3c7; padding:12px; border-radius:6px;\">💬 Forum Diskusi Mahasiswa Skillance</div>'\n});\n\napp.mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Elemen <code>&lt;component :is=\"tabAktif\"&gt;</code> secara mulus merender komponen TabMateri atau TabDiskusi sesuai tombol yang diklik.</p>\n</div>"
      },
      "vue_teleport": {
        "title": "Vue Teleport",
        "summary": "Merender elemen di luar pohon DOM komponen dengan `<Teleport to=\"body\">` untuk Modal, Dialog, dan Notification Toast.",
        "content": "<p class=\"lead\">Komponen bawaan <code>&lt;Teleport&gt;</code> memungkinkan kita merender bagian template di luar hirarki DOM komponen saat ini (misal langsung di bawah <code>&lt;body&gt;</code>).</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Solusi Masalah CSS Z-Index & Overflow: Modal yang diletakkan di dalam container ber-CSS <code>overflow: hidden</code> tidak akan terpotong batasnya.</li><li>Atribut <code>to</code>: Menerima target query selector seperti <code>to=\"body\"</code> atau <code>to=\"#modals\"</code>.</li><li>Reaktivitas Tetap Terhubung: Logika state dan props tetap terhubung ke komponen asal meskipun HTML-nya dipindahkan ke tempat lain di DOM.</li>\n    </ul>\n</div>",
        "example_title": "Render Modal Bebas dengan Teleport",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Teleport</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <button @click=\"bukaModal = true\">Buka Modal Dialog</button>\n\n<!-- Komponen Teleport memindahkan konten ke elemen body -->\n<div v-if=\"bukaModal\" style=\"position:fixed; top:20px; right:20px; background:#0d2e5c; color:#fff; padding:16px; border-radius:8px; box-shadow:0 8px 24px rgba(0,0,0,0.25); z-index:9999;\">\n    <strong style=\"color:#42b883;\">🚀 Notifikasi Teleport</strong>\n    <p style=\"margin:6px 0 10px 0; font-size:13px;\">Modal ini dirender bebas tanpa terhalang CSS parent!</p>\n    <button @click=\"bukaModal = false\" style=\"background:#ef4444; font-size:12px;\">Tutup</button>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            bukaModal: false\n        };\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Teleport memindahkan render visual ke titik DOM spesifik tanpa memutus komunikasi data reaktif dengan komponen induk.</p>\n</div>"
      },
      "vue_http": {
        "title": "Vue HTTP Request",
        "summary": "Komunikasi backend REST API: Mengambil data asinkron dengan Fetch API atau Axios, penanganan loading state, dan error handling.",
        "content": "<p class=\"lead\">Aplikasi Vue modern bertukar data dengan backend API (seperti Laravel, Node.js, atau Spring Boot) menggunakan HTTP request asinkron.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Pilihan Client HTTP: Menggunakan <code>fetch()</code> bawaan browser modern atau pustaka populer <code>axios</code>.</li><li>Pola 3 State: Selalu kelola tiga status: Data (sukses), Loading (sedang memuat), dan Error (gagal koneksi).</li><li>Hook Rekomendasi: Lakukan pemanggilan data awal di lifecycle hook <code>mounted()</code> atau <code>onMounted()</code>.</li>\n    </ul>\n</div>",
        "example_title": "Simulasi Panggilan HTTP Asinkron",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue HTTP Request</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Mengambil Data Asinkron (HTTP Fetch API):</p>\n<button @click=\"ambilData\" :disabled=\"memuat\">\n    {{ memuat ? 'Mengambil Data dari Server...' : 'Ambil Jadwal Kuliah' }}\n</button>\n\n<div v-if=\"jadwal.length\" style=\"margin-top:14px;\">\n    <div v-for=\"j in jadwal\" :key=\"j.hari\" style=\"background:#f1f5f9; padding:8px 12px; border-radius:6px; margin-bottom:6px; font-size:13px;\">\n        <strong>{{ j.hari }}:</strong> {{ j.mataKuliah }} ({{ j.jam }})\n    </div>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            memuat: false,\n            jadwal: []\n        };\n    },\n    methods: {\n        ambilData() {\n            this.memuat = true;\n            // Simulasi HTTP GET Request (fetch / axios)\n            setTimeout(() => {\n                this.jadwal = [\n                    { hari: \"Senin\", mataKuliah: \"Pemrograman Web Lanjut\", jam: \"08:00 - 10:30\" },\n                    { hari: \"Rabu\", mataKuliah: \"Rekayasa Perangkat Lunak\", jam: \"13:00 - 15:30\" }\n                ];\n                this.memuat = false;\n            }, 800);\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Tombol menampilkan status loading selama pemrosesan dan merender data jadwal begitu respon asinkron diterima.</p>\n</div>"
      },
      "vue_refs": {
        "title": "Vue Template Refs",
        "summary": "Mengakses elemen DOM fisik atau instance komponen anak secara langsung menggunakan atribut `ref` dan objek `this.$refs`.",
        "content": "<p class=\"lead\">Meskipun Vue mengedepankan model deklaratif, ada kalanya Anda tetap perlu mengakses elemen DOM langsung (seperti memberi fokus kursor atau mengontrol video canvas).</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Atribut <code>ref</code>: Diletakkan pada tag HTML: <code>&lt;input ref=\"myInput\"&gt;</code>.</li><li>Objek <code>this.$refs</code>: Mengembalikan elemen DOM murni setelah komponen terpasang di layar.</li><li>Waktu Akses: Nilai ref bernilai <code>undefined</code> selama tahap render awal dan baru tersedia setelah lifecycle hook <code>mounted()</code>.</li>\n    </ul>\n</div>",
        "example_title": "Manipulasi Fokus DOM dengan $refs",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Template Refs</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Fokus Input Otomatis via Template Ref:</p>\n<input type=\"text\" ref=\"inputFokus\" placeholder=\"Input ini akan langsung fokus!\">\n<div style=\"margin-top:10px;\">\n    <button @click=\"beriFokus\">Fokuskan Kursor ke Input</button>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    methods: {\n        beriFokus() {\n            // Mengakses elemen DOM langsung via this.$refs\n            this.$refs.inputFokus.focus();\n            this.$refs.inputFokus.select();\n        }\n    },\n    mounted() {\n        // Otomatis fokus saat halaman selesai dimuat\n        this.beriFokus();\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Metode <code>this.$refs.inputFokus.focus()</code> secara langsung memberikan fokus kursor pada elemen input HTML native.</p>\n</div>"
      },
      "vue_lifecycle_hooks": {
        "title": "Vue Lifecycle Hooks",
        "summary": "Tahapan siklus hidup komponen: `created` (inisialisasi), `mounted` (DOM terpasang), `updated` (data berubah), dan `unmounted` (pembersihan memori).",
        "content": "<p class=\"lead\">Setiap instance komponen Vue melewati serangkaian tahapan inisialisasi saat dibuat, diperbarui, dan dihancurkan.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li><code>created()</code>: Data reaktif dan event telah diatur, tetapi template belum dipasang ke layar DOM.</li><li><code>mounted()</code>: Komponen telah dirender sepenuhnya ke layar DOM; titik awal terbaik untuk pemanggilan API dan integrasi library luar.</li><li><code>updated()</code>: Dipicu setelah Virtual DOM selesai memperbarui tampilan akibat perubahan data.</li><li><code>unmounted()</code>: Dipicu saat komponen dihapus; krusial untuk mematikan interval timer (<code>clearInterval</code>) dan WebSocket.</li>\n    </ul>\n</div>",
        "example_title": "Visualisasi Siklus Hidup Lifecycle Hooks",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Lifecycle Hooks</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Riwayat Siklus Hidup Komponen:</p>\n<ul style=\"padding-left:18px; margin:0; font-size:13px; color:#475569;\">\n    <li v-for=\"log in logSiklus\" :key=\"log\">{{ log }}</li>\n</ul>\n<div style=\"margin-top:12px;\">\n    <button @click=\"counter++\">Update State (+1): {{ counter }}</button>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            counter: 0,\n            logSiklus: []\n        };\n    },\n    created() {\n        this.logSiklus.push(\"1. created: Data reaktif siap di memori\");\n    },\n    mounted() {\n        this.logSiklus.push(\"2. mounted: Elemen HTML telah dipasang di layar DOM\");\n    },\n    updated() {\n        this.logSiklus.push(\"3. updated: DOM diperbarui karena perubahan counter!\");\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Daftar log menampilkan kronologi eksekusi dari <code>created</code>, <code>mounted</code>, hingga pemanggilan <code>updated</code> saat tombol ditekan.</p>\n</div>"
      },
      "vue_provide_inject": {
        "title": "Vue Provide/Inject",
        "summary": "Dependency injection tingkat komponen: Mengatasi masalah prop drilling multi-level tanpa perlu mengoper props satu per satu.",
        "content": "<p class=\"lead\">Ketika pohon komponen memiliki kedalaman bertingkat (parent &gt; child &gt; grand-child), meneruskan props melalui setiap tingkat disebut 'prop drilling'.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Opsi <code>provide</code>: Komponen induk menyediakan data atau fungsi untuk semua komponen di bawah pohonnya.</li><li>Opsi <code>inject</code>: Komponen keturunan (berapapun dalamnya) dapat langsung menyuntikkan dan menggunakan data yang di-provide.</li><li>Reaktivitas Terjaga: Menggunakan <code>computed()</code> di provide untuk mempertahankan reaktivitas data.</li>\n    </ul>\n</div>",
        "example_title": "Penyaluran Data dengan Provide & Inject",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Provide/Inject</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Provide / Inject (Mencegah Prop Drilling):</p>\n<komponen-anak></komponen-anak>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        const app = createApp({\n    // Parent menyediakan (provide) data global ke seluruh turunan di bawahnya\n    provide() {\n        return {\n            temaGlobal: \"Dark Mode Emerald\",\n            penggunaLogin: \"Budi Santoso (Mahasiswa)\"\n        };\n    }\n});\n\napp.component('komponen-anak', {\n    template: `\n        <div style=\"background:#f1f5f9; padding:12px; border-radius:8px;\">\n            <p style=\"margin:0 0 6px 0; font-size:13px;\">Komponen Anak Tingkat 1</p>\n            <komponen-cucu></komponen-cucu>\n        </div>\n    `\n});\n\napp.component('komponen-cucu', {\n    // Komponen cucu menyuntikkan (inject) data tanpa lewat props anak\n    inject: ['temaGlobal', 'penggunaLogin'],\n    template: `\n        <div style=\"background:#0d2e5c; color:#fff; padding:10px; border-radius:6px; font-size:12px;\">\n            Cucu menerima data langsung: <br>\n            <strong>Pengguna:</strong> {{ penggunaLogin }} <br>\n            <strong>Tema:</strong> {{ temaGlobal }}\n        </div>\n    `\n});\n\napp.mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Komponen cucu langsung menerima data dari root parent tanpa perlu melewatkan props melalui komponen anak perantara.</p>\n</div>"
      },
      "vue_routing": {
        "title": "Vue Routing",
        "summary": "Navigasi halaman SPA dengan Vue Router: Komponen `<router-link>`, `<router-view>`, dynamic route params, dan navigation guards.",
        "content": "<p class=\"lead\">Vue Router adalah library perutean resmi untuk Vue.js yang menyelaraskan URL browser dengan komponen yang ditampilkan tanpa memicu reload halaman penuh.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Komponen <code>&lt;router-link&gt;</code>: Menggantikan tag <code>&lt;a&gt;</code> standar untuk navigasi halus di sisi klien.</li><li>Komponen <code>&lt;router-view&gt;</code>: Titik tempat komponen halaman aktif dirender.</li><li>Dynamic Route Matching: Mendukung rute dinamis dengan parameter seperti <code>/user/:id</code>.</li><li>Navigation Guards: Memeriksa hak akses (otentikasi login) sebelum mengizinkan pengguna berpindah ke halaman tertentu.</li>\n    </ul>\n</div>",
        "example_title": "Arsitektur Navigasi Vue Router",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Routing</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#0f172a; color:#f8fafc; padding:14px; border-radius:8px; font-family:monospace; font-size:13px;\">\n<span style=\"color:#94a3b8;\">// Vue Router (SPA Client-Side Navigation)</span><br>\n&lt;router-link to=\"/\"&gt;Beranda&lt;/router-link&gt; | <br>\n&lt;router-link to=\"/kursus\"&gt;Daftar Kursus&lt;/router-link&gt;<br><br>\n<span style=\"color:#38bdf8;\">&lt;!-- Wadah komponen halaman aktif dirender --&gt;</span><br>\n<span style=\"color:#42b883;\">&lt;router-view&gt;&lt;/router-view&gt;</span>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Vue Router menangani perubahan rute URL dan memperbarui tampilan <code>&lt;router-view&gt;</code> secara instan di browser.</p>\n</div>"
      },
      "vue_form_inputs": {
        "title": "Vue Form Inputs",
        "summary": "Membangun komponen input kustom yang mendukung `v-model` menggunakan prop `modelValue` dan event `update:modelValue`.",
        "content": "<p class=\"lead\">Anda dapat membuat komponen formulir kustom (seperti input rupiah, rating bintang, atau toggle switch) yang mendukung integrasi dua arah <code>v-model</code>.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Prop Standar <code>modelValue</code>: Properti bawaan tempat Vue menyalurkan data ke komponen anak.</li><li>Event Standar <code>update:modelValue</code>: Event yang harus dipancarkan oleh komponen anak saat nilai input berubah.</li><li>Custom Modifiers: Anda juga dapat menambahkan modifier kustom pada <code>v-model</code> komponen Anda.</li>\n    </ul>\n</div>",
        "example_title": "Implementasi Custom v-model Input",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Form Inputs</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Komponen Input Kustom dengan v-model:</p>\n<input-rupiah v-model=\"gajiTarget\"></input-rupiah>\n<div style=\"margin-top:10px; font-size:13px; color:#64748b;\">\n    Nilai Data Induk: <strong>Rp {{ gajiTarget.toLocaleString('id-ID') }}</strong>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        const app = createApp({\n    data() {\n        return {\n            gajiTarget: 7500000\n        };\n    }\n});\n\n// Custom component yang mendukung v-model\napp.component('input-rupiah', {\n    props: ['modelValue'],\n    emits: ['update:modelValue'],\n    template: `\n        <div style=\"display:flex; align-items:center; border:1px solid #cbd5e1; border-radius:6px; overflow:hidden; width:80%;\">\n            <span style=\"background:#e2e8f0; padding:8px 12px; font-weight:bold; color:#475569;\">Rp</span>\n            <input type=\"number\" \n                   :value=\"modelValue\" \n                   @input=\"$emit('update:modelValue', Number($event.target.value))\"\n                   style=\"border:none; border-radius:0; flex:1;\">\n        </div>\n    `\n});\n\napp.mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Komponen anak <code>input-rupiah</code> menyelaraskan nilai input melalui prop <code>modelValue</code> dan event <code>update:modelValue</code>.</p>\n</div>"
      },
      "vue_animations": {
        "title": "Vue Animations",
        "summary": "Menganimasikan elemen masuk dan keluar dengan komponen bawaan `<Transition>` dan kelas transisi CSS.",
        "content": "<p class=\"lead\">Vue menyediakan komponen pembungkus <code>&lt;Transition&gt;</code> untuk menerapkan animasi transisi saat elemen masuk atau keluar dari DOM via <code>v-if</code> atau <code>v-show</code>.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>6 Kelas Transisi Otomatis: <code>v-enter-from</code>, <code>v-enter-active</code>, <code>v-enter-to</code>, <code>v-leave-from</code>, <code>v-leave-active</code>, <code>v-leave-to</code>.</li><li>Transisi CSS & Keyframes: Dapat dipadukan dengan library CSS populer seperti Animate.css.</li><li>JavaScript Hooks: Mendukung event transisi JavaScript seperti <code>@before-enter</code>, <code>@enter</code>, <code>@leave</code> untuk animasi via GSAP.</li>\n    </ul>\n</div>",
        "example_title": "Penerapan Transisi Animasi Vue",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        .animasi-fade { animation: munculHalus 0.4s ease-out; }\n@keyframes munculHalus {\n    from { opacity: 0; transform: translateY(-10px); }\n    to { opacity: 1; transform: translateY(0); }\n}\n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Animations</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <button @click=\"muncul = !muncul\">Toggle Animasi Kotak</button>\n<div style=\"margin-top:14px; min-height:80px;\">\n    <!-- Transisi animasi Vue -->\n    <div v-if=\"muncul\" class=\"animasi-fade\" style=\"background:#42b883; color:#fff; padding:16px; border-radius:8px; text-align:center;\">\n        ✨ Elemen Masuk dengan Animasi Halus!\n    </div>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            muncul: true\n        };\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Komponen transisi secara otomatis mengatur kelas CSS animasi saat elemen dipasang atau dicopot dari tampilan.</p>\n</div>"
      },
      "vue_animations_v_for": {
        "title": "Vue Animations with v-for",
        "summary": "Animasi daftar koleksi menggunakan `<TransitionGroup>`: Mendukung transisi perpindahan posisi (FLIP animation).",
        "content": "<p class=\"lead\">Untuk menganimasikan banyak elemen yang dihasilkan oleh perulangan <code>v-for</code>, Vue menghadirkan komponen <code>&lt;TransitionGroup&gt;</code>.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Wajib Tag Kontainer: Berbeda dengan <code>&lt;Transition&gt;</code> tunggal, <code>&lt;TransitionGroup&gt;</code> merender elemen pembungkus nyata (default <code>&lt;span&gt;</code> atau kustom via <code>tag=\"ul\"</code>).</li><li>Wajib Atribut <code>:key</code>: Setiap elemen wajib memiliki key unik agar transisi posisi dapat dihitung secara matematis.</li><li>Transisi Perpindahan (Move Transitions): Mendukung kelas <code>v-move</code> yang menerapkan teknik animasi FLIP untuk pergeseran posisi halus.</li>\n    </ul>\n</div>",
        "example_title": "Animasi List Dinamis dengan TransitionGroup",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        .angka-badge {\n    background: #0284c7; color: white; padding: 6px 14px; border-radius: 20px; font-weight: bold; font-size: 13px;\n    animation: zoomMasuk 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n}\n@keyframes zoomMasuk {\n    from { opacity: 0; transform: scale(0.5); }\n    to { opacity: 1; transform: scale(1); }\n}\n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Animations with v-for</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"margin-bottom:12px;\">\n    <button @click=\"tambahItem\">+ Tambah Angka</button>\n    <button @click=\"hapusItem\" style=\"background:#ef4444; margin-left:6px;\">- Hapus Angka</button>\n</div>\n<div style=\"display:flex; gap:8px; flex-wrap:wrap;\">\n    <span v-for=\"n in angkaList\" :key=\"n\" class=\"angka-badge\">\n        {{ n }}\n    </span>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            angkaList: [10, 20, 30, 40]\n        };\n    },\n    methods: {\n        tambahItem() {\n            const baru = Math.floor(Math.random() * 90) + 10;\n            this.angkaList.push(baru);\n        },\n        hapusItem() {\n            this.angkaList.pop();\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Setiap badge angka yang ditambahkan atau dihapus mengalami animasi penskalaan halus berkat transisi daftar.</p>\n</div>"
      },
      "vue_build": {
        "title": "Vue Build",
        "summary": "Mempersiapkan aplikasi untuk rilis produksi: Perintah `npm run build`, pembuatan direktori `/dist`, minifikasi, dan optimasi aset.",
        "content": "<p class=\"lead\">Sebelum merilis aplikasi ke server produksi (seperti Nginx di VPS atau Vercel/Netlify), berkas kode sumber wajib dikompilasi dan diminifikasi.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Perintah <code>npm run build</code>: Memanggil bundler Vite (Rollup) untuk memproses seluruh komponen <code>.vue</code>, CSS, dan aset gambar.</li><li>Direktori <code>/dist</code>: Menghasilkan berkas statis murni (.html, .js, .css) yang siap disajikan oleh sembarang web server statis.</li><li>Code Splitting: Secara otomatis memecah berkas JavaScript menjadi beberapa potongan (chunks) agar halaman pertama termuat super cepat.</li>\n    </ul>\n</div>",
        "example_title": "Output Terminal Build Produksi Vite",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Build</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#0f172a; color:#f8fafc; padding:16px; border-radius:8px; font-family:monospace; font-size:13px;\">\n    <div style=\"color:#64748b;\"># Perintah Build Produksi:</div>\n    <div style=\"color:#38bdf8;\">$ npm run build</div><br>\n    <div style=\"color:#42b883;\">vite v5.2.0 building for production...</div>\n    <div style=\"color:#e2e8f0;\">✓ 42 modules transformed.</div>\n    <div style=\"color:#4ade80;\">dist/index.html &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;0.45 kB</div>\n    <div style=\"color:#4ade80;\">dist/assets/index-D7s8a.css &nbsp;&nbsp;3.12 kB │ gzip: 1.05 kB</div>\n    <div style=\"color:#4ade80;\">dist/assets/index-B4k9x.js &nbsp;&nbsp;58.20 kB │ gzip: 22.40 kB</div>\n    <div style=\"color:#22c55e; margin-top:6px;\">✓ built in 420ms. Siap deploy ke VPS!</div>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Proses build menghasilkan berkas terminifikasi terkompresi gzip yang sangat ringan untuk waktu muat halaman secepat kilat.</p>\n</div>"
      },
      "vue_composition_api": {
        "title": "Vue Composition API",
        "summary": "Paradigma modern Vue 3: Fungsi `setup()`, primitif reaktif `ref()` & `reactive()`, computed, lifecycle hooks, dan composable reusable functions.",
        "content": "<p class=\"lead\">Composition API adalah inovasi terbesar di Vue 3 yang memungkinkan pengelompokan logika kode berdasarkan fitur fungsional, bukan berdasarkan opsi struktur.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Primitif <code>ref()</code>: Membungkus nilai primitif (string, number, boolean) ke dalam objek reaktif dengan properti <code>.value</code>.</li><li>Primitif <code>reactive()</code>: Membuat objek bersarang menjadi proksi reaktif langsung.</li><li>Sintaks Ringkas <code>&lt;script setup&gt;</code>: Menghilangkan boilerplate <code>export default</code> dan <code>return</code>.</li><li>Custom Composables: Mengekstrak logika reaktif ke dalam fungsi <code>useCounter()</code>, <code>useAuth()</code> yang dapat digunakan kembali di banyak komponen.</li>\n    </ul>\n</div>",
        "example_title": "Contoh Sintaks setup() Composition API",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Composition API</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p><strong>Vue 3 Composition API (ref & computed):</strong></p>\n<div style=\"background:#f1f5f9; padding:12px; border-radius:8px; margin-bottom:10px;\">\n    Jumlah Klik: <strong style=\"color:#42b883; font-size:18px;\">{{ jumlah }}</strong><br>\n    Nilai Kuadrat: <strong>{{ kuadrat }}</strong>\n</div>\n<button @click=\"tambah\">+ Tambah State (ref)</button>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    setup() {\n        // Mendefinisikan state reaktif menggunakan ref()\n        const jumlah = ref(5);\n\n        // Computed property di Composition API\n        const kuadrat = computed(() => jumlah.value * jumlah.value);\n\n        function tambah() {\n            jumlah.value++;\n        }\n\n        // Ekspos ke template\n        return {\n            jumlah,\n            kuadrat,\n            tambah\n        };\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Fungsi <code>setup()</code> menggunakan <code>ref()</code> dan <code>computed()</code> untuk mendefinisikan reaktivitas modern yang sangat fleksibel.</p>\n</div>"
      }
    },
    "Vue Cert": {
      "vue_exam": {
        "title": "Vue Certificate",
        "summary": "Panduan resmi Ujian Sertifikasi Kompetensi Vue.js Frontend Developer Skillance Academy Indonesia.",
        "content": "<p class=\"lead\">Ujian Sertifikasi Vue.js Skillance dirancang untuk memvalidasi kemahiran teknis Anda dalam membangun antarmuka web modern, reaktivitas komponen, dan integrasi API.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Materi yang Diuji: Directives, Form Binding, Props & Emits, Slots, Lifecycle Hooks, Vue Router, dan Composition API.</li><li>Format Evaluasi: Soal analisis kode, debugging reaktivitas, dan pembuatan komponen interaktif.</li><li>Peluang Karir: Sertifikat digital yang dapat disematkan di profil LinkedIn dan portofolio kerja Frontend Engineer.</li>\n    </ul>\n</div>",
        "example_title": "Informasi Evaluasi Kompetensi Vue.js",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Certificate</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#f8fafc; border:2px dashed #42b883; border-radius:10px; padding:18px; text-align:center;\">\n    <h3 style=\"color:#0d2e5c; margin:0 0 6px 0;\">Sertifikasi Resmi Vue.js Frontend Developer</h3>\n    <p style=\"color:#64748b; font-size:13px; margin:0 0 14px 0;\">Skillance Academy Indonesia</p>\n    <div style=\"display:flex; justify-content:center; gap:8px; flex-wrap:wrap; margin-bottom:14px;\">\n        <span class=\"pill\" style=\"background:#42b883; color:#fff;\">Reaktivitas Vue 3</span>\n        <span class=\"pill\" style=\"background:#0284c7; color:#fff;\">Komponen & Props</span>\n        <span class=\"pill\" style=\"background:#f59e0b; color:#fff;\">Composition API</span>\n        <span class=\"pill\" style=\"background:#6366f1; color:#fff;\">Vite & Routing</span>\n    </div>\n    <button @click=\"cekKesiapan\">Cek Status Kesiapan Ujian &raquo;</button>\n    <p v-if=\"pesan\" style=\"color:#16a34a; font-weight:bold; margin-top:10px; font-size:13px;\">{{ pesan }}</p>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            pesan: \"\"\n        };\n    },\n    methods: {\n        cekKesiapan() {\n            this.pesan = \"Status: Anda telah memenuhi syarat untuk mengikuti evaluasi sertifikasi Vue.js!\";\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Kuasai ke-56 topik di dalam tutorial ini untuk memastikan kelulusan ujian kompetensi dengan nilai maksimal.</p>\n</div>"
      }
    },
    "Vue Reference": {
      "vue_ref_builtin_attributes": {
        "title": "Vue Built-in Attributes",
        "summary": "Referensi atribut bawaan spesial Vue: Atribut `key`, `ref`, dan `is` untuk pengontrolan Virtual DOM.",
        "content": "<p class=\"lead\">Vue menyediakan atribut spesial yang diperlakukan secara khusus oleh compiler dan tidak diteruskan sebagai atribut HTML biasa.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li><code>key</code>: Digunakan bersama <code>v-for</code> untuk mengidentifikasi VNodes secara presisi saat update array.</li><li><code>ref</code>: Menautkan elemen DOM atau child component ke properti <code>$refs</code>.</li><li><code>is</code>: Digunakan pada tag <code>&lt;component :is=\"...\"&gt;</code> untuk rendering dinamis.</li>\n    </ul>\n</div>",
        "example_title": "Katalog Atribut Bawaan Vue",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Built-in Attributes</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#0f172a; color:#f8fafc; padding:14px; border-radius:8px; font-family:monospace; font-size:13px;\">\n<span style=\"color:#42b883;\">// Atribut Bawaan Spesial Vue 3:</span><br>\n- <strong>key</strong> : Petunjuk unik bagi algoritma rekonsiliasi Virtual DOM<br>\n- <strong>ref</strong> : Mendaftarkan referensi langsung ke elemen DOM / instance komponen<br>\n- <strong>is</strong>  : Mengubah elemen biasa menjadi komponen dinamis\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Atribut spesial ini memberikan instruksi langsung kepada kompiler Vue untuk mengatur lifecycle dan identitas elemen.</p>\n</div>"
      },
      "vue_ref_builtin_components": {
        "title": "Vue Built-in Components",
        "summary": "Referensi komponen bawaan: `<Transition>`, `<TransitionGroup>`, `<KeepAlive>`, `<Teleport>`, dan `<Suspense>`.",
        "content": "<p class=\"lead\">Vue menyertakan sekumpulan komponen inti siap pakai yang dapat langsung dipanggil tanpa perlu melakukan registrasi manual.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li><code>&lt;Transition&gt;</code>: Memberikan efek animasi transisi pada elemen tunggal.</li><li><code>&lt;KeepAlive&gt;</code>: Menyimpan status instance komponen yang tidak aktif agar tidak hilang saat berganti tab.</li><li><code>&lt;Teleport&gt;</code>: Menembus batasan tata letak DOM saat ini untuk merender modal di root body.</li><li><code>&lt;Suspense&gt;</code>: Menampilkan fallback loading saat menunggu komponen asinkron selesai diunduh.</li>\n    </ul>\n</div>",
        "example_title": "5 Komponen Bawaan Resmi Vue 3",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Built-in Components</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#0f172a; color:#f8fafc; padding:14px; border-radius:8px; font-family:monospace; font-size:13px;\">\n<span style=\"color:#38bdf8;\">// Komponen Bawaan (Built-in Components):</span><br>\n1. <strong>&lt;Transition&gt;</strong>      : Transisi animasi masuk/keluar elemen tunggal<br>\n2. <strong>&lt;TransitionGroup&gt;</strong> : Animasi list dinamis (v-for)<br>\n3. <strong>&lt;KeepAlive&gt;</strong>       : Menyimpan cache state komponen dinamis<br>\n4. <strong>&lt;Teleport&gt;</strong>        : Merender elemen ke target DOM lain (seperti body)<br>\n5. <strong>&lt;Suspense&gt;</strong>        : Menangani komponen dengan dependensi asinkron\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Seluruh komponen bawaan ini terintegrasi langsung di dalam runtime Vue 3 dan siap pakai tanpa modul tambahan.</p>\n</div>"
      },
      "vue_ref_builtin_elements": {
        "title": "Vue Built-in Elements",
        "summary": "Referensi elemen template semu: `<component>`, `<slot>`, dan `<template>` untuk pengelompokan tanpa wrapper div ekstra.",
        "content": "<p class=\"lead\">Elemen-elemen ini bertindak sebagai direktif struktural tingkat tinggi di dalam template dan tidak menghasilkan tag pembungkus ekstra di DOM akhir.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li><code>&lt;component&gt;</code>: Digunakan bersama atribut <code>:is</code>.</li><li><code>&lt;slot&gt;</code>: Saluran penyalur konten kustom dari komponen parent.</li><li><code>&lt;template&gt;</code>: Tag tak kasat mata di DOM browser, sangat berguna untuk membungkus banyak elemen yang memiliki kondisi <code>v-if</code> atau <code>v-for</code> yang sama.</li>\n    </ul>\n</div>",
        "example_title": "Katalog Elemen Bawaan Vue 3",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Built-in Elements</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#0f172a; color:#f8fafc; padding:14px; border-radius:8px; font-family:monospace; font-size:13px;\">\n<span style=\"color:#f472b6;\">// Elemen Spesial Template:</span><br>\n- <strong>&lt;component&gt;</strong> : Placeholder untuk merender komponen dinamis<br>\n- <strong>&lt;slot&gt;</strong>      : Outlet distribusi konten di dalam komponen anak<br>\n- <strong>&lt;template&gt;</strong>  : Wadah semu tak terlihat untuk v-if atau v-for majemuk\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Menggunakan <code>&lt;template&gt;</code> menjaga kebersihan struktur DOM tanpa menimbulkan 'div soup' yang tidak perlu.</p>\n</div>"
      },
      "vue_ref_component_instance": {
        "title": "Vue Component Instance",
        "summary": "Properti dan metode instance komponen berawalan dollar (`$data`, `$props`, `$el`, `$refs`, `$emit()`, `$slots`).",
        "content": "<p class=\"lead\">Di dalam Options API, objek <code>this</code> merepresentasikan instance komponen aktif yang mengekspos properti bawaan berawalan tanda <code>$</code>.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li><code>$el</code>: Pointer langsung ke elemen root DOM dari komponen aktif.</li><li><code>$refs</code>: Kamus objek elemen DOM yang diberi atribut <code>ref</code>.</li><li><code>$emit()</code>: Memancarkan sinyal event kustom ke komponen induk.</li><li><code>$attrs</code>: Atribut fallthrough yang tidak ditangkap oleh deklarasi props.</li>\n    </ul>\n</div>",
        "example_title": "Properti Bawaan Instance Vue ($)",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Component Instance</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#0f172a; color:#f8fafc; padding:14px; border-radius:8px; font-family:monospace; font-size:13px;\">\n<span style=\"color:#4ade80;\">// Properti Instance Komponen ($):</span><br>\n- <strong>$data</strong>    : Akses objek data reaktif mentah<br>\n- <strong>$props</strong>   : Akses seluruh properti props yang diterima<br>\n- <strong>$el</strong>      : Elemen root DOM fisik dari komponen<br>\n- <strong>$refs</strong>    : Objek koleksi template refs<br>\n- <strong>$emit()</strong>  : Fungsi pemancar event kustom<br>\n- <strong>$slots</strong>   : Akses programatik konten slot\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Properti berawalan $ sengaja diberi nama unik untuk membedakannya dari data dan methods yang didefinisikan oleh developer.</p>\n</div>"
      },
      "vue_ref_directives": {
        "title": "Vue Directives",
        "summary": "Lembar contekan referensi lengkap seluruh direktif Vue 3: Sintaks, argumen, modifier, dan fungsi operasionalnya.",
        "content": "<p class=\"lead\">Ringkasan teknis cepat seluruh direktif bawaan Vue 3 yang wajib dikuasai oleh setiap frontend developer.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Directives Kontrol Data: <code>v-model</code>, <code>v-bind</code>, <code>v-text</code>, <code>v-html</code>.</li><li>Directives Kontrol Alur: <code>v-if</code>, <code>v-else</code>, <code>v-show</code>, <code>v-for</code>.</li><li>Directives Optimasi: <code>v-once</code>, <code>v-memo</code> (C++-like caching vnode di Vue 3.2+), <code>v-pre</code>, <code>v-cloak</code>.</li>\n    </ul>\n</div>",
        "example_title": "Cheatsheet Direktif Resmi Vue 3",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Directives Reference</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#0f172a; color:#f8fafc; padding:14px; border-radius:8px; font-family:monospace; font-size:12px; line-height:1.7;\">\n<span style=\"color:#f59e0b;\">// Lembar Contekan Lengkap Directives Vue 3:</span><br>\n• <strong>v-text</strong> : Render teks murni<br>\n• <strong>v-html</strong> : Render konten HTML kaya<br>\n• <strong>v-show</strong> : Toggle via CSS display: none<br>\n• <strong>v-if / v-else-if / v-else</strong> : Kondisional rendering di DOM<br>\n• <strong>v-for</strong>  : Perulangan koleksi data array/objek<br>\n• <strong>v-on (@)</strong>: Mengikat event listener pengguna<br>\n• <strong>v-bind (:)</strong>: Mengikat atribut HTML dinamis<br>\n• <strong>v-model</strong> : Two-way data binding input form<br>\n• <strong>v-slot (#)</strong>: Menyalurkan konten ke slot komponen\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Kompiler Vue mengurai direktif-direktif ini menjadi fungsi render JavaScript teroptimasi saat kompilasi.</p>\n</div>"
      },
      "vue_ref_options": {
        "title": "Vue Instance Options",
        "summary": "Struktur lengkap Options API: Opsi `data`, `props`, `computed`, `methods`, `watch`, `components`, dan `emits`.",
        "content": "<p class=\"lead\">Options API mengorganisasi kode komponen berdasarkan kategori opsi yang sudah ditentukan, mempermudah pemula dalam menstrukturkan logika aplikasi.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>State: <code>data()</code> mengembalikan objek state awal.</li><li>Turunan: <code>computed</code> menyimpan kalkulasi yang di-cache.</li><li>Aksi: <code>methods</code> menampung fungsi penanganan aksi dan event.</li><li>Reaksi: <code>watch</code> mengamati mutasi data untuk side-effects.</li>\n    </ul>\n</div>",
        "example_title": "Katalog Opsi Komponen Vue",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Instance Options</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#0f172a; color:#f8fafc; padding:14px; border-radius:8px; font-family:monospace; font-size:13px;\">\n<span style=\"color:#38bdf8;\">// Struktur Standar Options API:</span><br>\nexport default {<br>\n&nbsp;&nbsp;<strong>data()</strong> { return { ... } },<br>\n&nbsp;&nbsp;<strong>props</strong>: { ... },<br>\n&nbsp;&nbsp;<strong>computed</strong>: { ... },<br>\n&nbsp;&nbsp;<strong>methods</strong>: { ... },<br>\n&nbsp;&nbsp;<strong>watch</strong>: { ... },<br>\n&nbsp;&nbsp;<strong>components</strong>: { ... },<br>\n&nbsp;&nbsp;<strong>emits</strong>: [ ... ]<br>\n}\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Options API memisahkan perhatian kode berdasarkan peran masing-masing opsi secara jelas dan terprediksi.</p>\n</div>"
      },
      "vue_ref_lifecycle_hooks": {
        "title": "Vue Lifecycle Hooks",
        "summary": "Diagram dan rujukan lengkap alur Lifecycle Hooks: Dari inisialisasi reaktivitas, mounting DOM, hingga pembersihan unmounting.",
        "content": "<p class=\"lead\">Panduan komprehensif urutan eksekusi lifecycle hooks yang menjamin Anda meletakkan kode inisialisasi pada waktu yang tepat.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Tahap Pembentukan (Creation): <code>created()</code> - tempat aman pertama untuk membaca <code>this.data</code>.</li><li>Tahap Pemasangan (Mounting): <code>mounted()</code> - tempat pertama elemen DOM fisik dapat dimanipulasi.</li><li>Tahap Pembongkaran (Unmounting): <code>unmounted()</code> - tempat krusial membersihkan event listener global dan timers.</li>\n    </ul>\n</div>",
        "example_title": "Rujukan Kronologi Siklus Hidup Vue",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Lifecycle Hooks Reference</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#0f172a; color:#f8fafc; padding:14px; border-radius:8px; font-family:monospace; font-size:12px; line-height:1.7;\">\n<span style=\"color:#42b883;\">// Diagram Alur Lifecycle Hooks Lengkap:</span><br>\n1. <strong>beforeCreate / created</strong> : Inisialisasi state reaktif<br>\n2. <strong>beforeMount / mounted</strong>   : Pemasangan DOM ke layar browser<br>\n3. <strong>beforeUpdate / updated</strong> : Siklus render ulang saat data berubah<br>\n4. <strong>beforeUnmount / unmounted</strong>: Pembersihan memori saat komponen dihapus\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Memahami urutan siklus hidup menghindarkan Anda dari bug membaca elemen DOM yang belum selesai dirender.</p>\n</div>"
      }
    },
    "Vue Examples": {
      "vue_examples": {
        "title": "Vue Examples",
        "summary": "Kumpulan contoh kode praktis: Aplikasi Todo List interaktif dengan penambahan tugas, toggle status selesai, dan filter aktif.",
        "content": "<p class=\"lead\">Contoh aplikasi dunia nyata yang mengintegrasikan reaktivitas, directive <code>v-model</code>, perulangan <code>v-for</code>, dan computed property.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Two-Way Input: Mengikat teks tugas baru via <code>v-model</code>.</li><li>Manipulasi Array Reaktif: Menambahkan item via <code>push()</code> dan menghapus via <code>splice()</code>.</li><li>Perhitungan Otomatis: Menghitung sisa tugas secara reaktif menggunakan <code>computed</code>.</li>\n    </ul>\n</div>",
        "example_title": "Aplikasi Todo List Reaktif",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Examples</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p><strong>Aplikasi Todo List Interaktif:</strong></p>\n<div style=\"display:flex; gap:6px; margin-bottom:12px;\">\n    <input type=\"text\" v-model=\"tugasBaru\" @keyup.enter=\"tambahTugas\" placeholder=\"Tambah kegiatan baru...\" style=\"flex:1;\">\n    <button @click=\"tambahTugas\">Tambah</button>\n</div>\n<ul style=\"padding-left:0; list-style:none; margin:0;\">\n    <li v-for=\"(t, i) in list\" :key=\"i\" style=\"display:flex; justify-content:space-between; align-items:center; padding:8px 0; border-bottom:1px solid #f1f5f9;\">\n        <label style=\"display:flex; align-items:center; gap:8px; cursor:pointer;\">\n            <input type=\"checkbox\" v-model=\"t.selesai\">\n            <span :style=\"{ textDecoration: t.selesai ? 'line-through' : 'none', color: t.selesai ? '#94a3b8' : '#1e293b' }\">{{ t.teks }}</span>\n        </label>\n        <button @click=\"hapusTugas(i)\" style=\"background:#ef4444; padding:4px 8px; font-size:11px;\">Hapus</button>\n    </li>\n</ul>\n<div style=\"margin-top:12px; font-size:12px; color:#64748b;\">\n    Tersisa: {{ sisaTugas }} tugas belum selesai\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            tugasBaru: \"\",\n            list: [\n                { teks: \"Pelajari Direktif Vue 3\", selesai: true },\n                { teks: \"Uji Coba Two-Way Binding\", selesai: false }\n            ]\n        };\n    },\n    computed: {\n        sisaTugas() {\n            return this.list.filter(t => !t.selesai).length;\n        }\n    },\n    methods: {\n        tambahTugas() {\n            if (!this.tugasBaru.trim()) return;\n            this.list.push({ teks: this.tugasBaru.trim(), selesai: false });\n            this.tugasBaru = \"\";\n        },\n        hapusTugas(index) {\n            this.list.splice(index, 1);\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Aplikasi mendemonstrasikan bagaimana manipulasi data array langsung memperbarui tampilan antarmuka secara otomatis.</p>\n</div>"
      },
      "vue_editor": {
        "title": "Vue Editor",
        "summary": "Membangun Live Text Editor dengan preview reaktif instan, kalkulasi jumlah kata otomatis, dan manipulasi textarea.",
        "content": "<p class=\"lead\">Studi kasus pembuatan editor teks waktu nyata yang menunjukkan kekuatan sinkronisasi data reaktif Vue.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Input Multiline: Mengikat elemen <code>&lt;textarea&gt;</code> ke variabel reaktif.</li><li>Kalkulasi Kata Dinamis: Menghitung total kata dan karakter menggunakan ekspresi reguler di dalam computed property.</li><li>Pratinjau Preservasi Format: Menggunakan aturan CSS <code>white-space: pre-wrap</code> untuk mempertahankan jeda baris.</li>\n    </ul>\n</div>",
        "example_title": "Live Text Editor & Word Counter",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Editor</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p>Live Teks Editor & Previewer:</p>\n<textarea v-model=\"kontenTeks\" rows=\"4\" style=\"width:100%;\" placeholder=\"Ketik kalimat di sini...\"></textarea>\n<div style=\"margin-top:12px; background:#f8fafc; border:1px solid #cbd5e1; border-radius:8px; padding:12px;\">\n    <strong>Pratinjau Hasil:</strong>\n    <p style=\"margin:6px 0 0 0; color:#0d2e5c; white-space:pre-wrap;\">{{ kontenTeks }}</p>\n</div>\n<small style=\"color:#64748b;\">Jumlah Kata: {{ totalKata }} | Jumlah Karakter: {{ kontenTeks.length }}</small>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            kontenTeks: \"Selamat datang di Live Editor Skillance Academy!\nKetik teks di atas untuk melihat sinkronisasi instan.\"\n        };\n    },\n    computed: {\n        totalKata() {\n            const trimmed = this.kontenTeks.trim();\n            if (!trimmed) return 0;\n            return trimmed.split(/\\s+/).length;\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Setiap penambahan atau penghapusan kata pada textarea langsung memperbarui kotak pratinjau dan statistik kata.</p>\n</div>"
      },
      "vue_exercises": {
        "title": "Vue Exercises",
        "summary": "Latihan praktis interaktif: Mengendalikan gaya visual secara dinamis, manipulasi event klik, dan validasi input.",
        "content": "<p class=\"lead\">Latihan interaktif mandiri untuk menguji pemahaman Anda terhadap binding gaya CSS dinamis dan event handling di Vue 3.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Latihan 1: Mengubah warna kotak berdasarkan tombol yang ditekan pengguna.</li><li>Latihan 2: Membangun tombol counter dengan nilai step kelipatan kustom.</li><li>Latihan 3: Membuat filter pencarian list produk toko online secara real-time.</li>\n    </ul>\n</div>",
        "example_title": "Latihan Dynamic Style Switching",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Exercises</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <p><strong>Latihan Interaktif: Pengubah Warna Dinamis</strong></p>\n<div :style=\"{ background: warnaTerpilih, color: '#fff', padding: '20px', borderRadius: '8px', textAlign: 'center', fontWeight: 'bold' }\">\n    Warna Aktif: {{ warnaTerpilih }}\n</div>\n<div style=\"display:flex; gap:8px; margin-top:12px;\">\n    <button @click=\"warnaTerpilih = '#42b883'\" style=\"background:#42b883;\">Hijau Vue</button>\n    <button @click=\"warnaTerpilih = '#0284c7'\" style=\"background:#0284c7;\">Biru Laut</button>\n    <button @click=\"warnaTerpilih = '#f59e0b'\" style=\"background:#f59e0b;\">Kuning Emas</button>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            warnaTerpilih: \"#42b883\"\n        };\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Menekan salah satu tombol warna akan memperbarui state <code>warnaTerpilih</code> dan seketika mengubah inline CSS kotak.</p>\n</div>"
      },
      "vue_quiz": {
        "title": "Vue Quiz",
        "summary": "Kuis evaluasi pengetahuan mandiri: Menguji pemahaman konsep reaktivitas, direktif inti, dan alur komponen Vue.",
        "content": "<p class=\"lead\">Uji pemahaman Anda terhadap konsep dasar Vue 3 dengan serangkaian pertanyaan interaktif pilihan ganda.</p>\n<div class=\"card bg-light border-0 p-3 mb-3 rounded-3\">\n    <h6 class=\"fw-bold text-navy mb-2\"><i class=\"fa-solid fa-code text-success me-2\"></i>Konsep Kunci Materi:</h6>\n    <ul class=\"mb-0 small\" style=\"line-height: 1.8;\">\n        <li>Soal Reaktivitas: Perbedaan antara <code>ref</code> dan <code>reactive</code>.</li><li>Soal Direktif: Kapan harus memilih <code>v-if</code> dibanding <code>v-show</code>.</li><li>Soal Arsitektur: Bagaimana cara komponen anak berkomunikasi ke komponen induk via <code>$emit</code>.</li>\n    </ul>\n</div>",
        "example_title": "Simulasi Kuis Interaktif Vue",
        "example_code": "<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <script src=\"https://unpkg.com/vue@3/dist/vue.global.js\"></script>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n            background: #f8fafc;\n            color: #1e293b;\n            padding: 24px;\n            margin: 0;\n            line-height: 1.6;\n        }\n        .vue-app-container {\n            background: white;\n            border-radius: 12px;\n            padding: 24px;\n            max-width: 520px;\n            margin: 0 auto;\n            box-shadow: 0 4px 15px rgba(0,0,0,0.06);\n            border-top: 4px solid #42b883;\n        }\n        .vue-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 18px;\n            padding-bottom: 12px;\n            border-bottom: 1px solid #f1f5f9;\n        }\n        .vue-title {\n            font-weight: 700;\n            color: #0d2e5c;\n            font-size: 16px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n        .badge-vue {\n            background: #42b883;\n            color: white;\n            padding: 3px 10px;\n            border-radius: 20px;\n            font-size: 11px;\n            font-weight: 700;\n        }\n        button {\n            background: #42b883;\n            color: white;\n            border: none;\n            padding: 8px 16px;\n            border-radius: 6px;\n            cursor: pointer;\n            font-weight: 600;\n            font-size: 13px;\n            transition: all 0.2s;\n        }\n        button:hover {\n            background: #33a06f;\n        }\n        input, select, textarea {\n            padding: 8px 12px;\n            border: 1px solid #cbd5e1;\n            border-radius: 6px;\n            font-size: 14px;\n            box-sizing: border-box;\n            outline: none;\n        }\n        input:focus, select:focus, textarea:focus {\n            border-color: #42b883;\n            box-shadow: 0 0 0 3px rgba(66, 184, 131, 0.15);\n        }\n        .pill {\n            display: inline-block;\n            background: #e2e8f0;\n            padding: 4px 10px;\n            border-radius: 12px;\n            font-size: 12px;\n            margin: 2px;\n        }\n        \n    </style>\n</head>\n<body>\n    <div id=\"app\" class=\"vue-app-container\">\n        <div class=\"vue-header\">\n            <span class=\"vue-title\">🟢 Vue Quiz</span>\n            <span class=\"badge-vue\">Vue 3 Live</span>\n        </div>\n        <div style=\"background:#f1f5f9; padding:16px; border-radius:8px;\">\n    <p style=\"margin:0 0 10px 0; font-weight:bold;\">Kuis: Manakah direktif yang digunakan untuk two-way data binding pada form di Vue?</p>\n    <div style=\"display:flex; flex-direction:column; gap:6px;\">\n        <label><input type=\"radio\" value=\"a\" v-model=\"jawaban\"> A. v-bind</label>\n        <label><input type=\"radio\" value=\"b\" v-model=\"jawaban\"> B. v-on</label>\n        <label><input type=\"radio\" value=\"c\" v-model=\"jawaban\"> C. v-model</label>\n    </div>\n    <button @click=\"periksaJawaban\" style=\"margin-top:12px;\">Periksa Jawaban</button>\n    <p v-if=\"hasil\" :style=\"{ color: hasil === 'Benar!' ? '#16a34a' : '#ef4444', fontWeight: 'bold', margin: '10px 0 0 0' }\">\n        {{ hasil }}\n    </p>\n</div>\n    </div>\n\n    <script>\n        const { createApp, ref, reactive, computed, watch, onMounted } = Vue;\n        createApp({\n    data() {\n        return {\n            jawaban: \"\",\n            hasil: \"\"\n        };\n    },\n    methods: {\n        periksaJawaban() {\n            if (this.jawaban === 'c') {\n                this.hasil = \"Benar! v-model adalah direktif untuk two-way data binding.\";\n            } else {\n                this.hasil = \"Kurang tepat. Coba lagi! Petunjuk: Berawalan huruf M.\";\n            }\n        }\n    }\n}).mount('#app');\n    </script>\n</body>\n</html>",
        "explanation": "<div class=\"mt-3\">\n    <h6 class=\"fw-bold text-navy\"><i class=\"fa-solid fa-circle-info text-success me-2\"></i>Penjelasan Kode & Reaktivitas:</h6>\n    <p class=\"small text-secondary mb-0\" style=\"line-height: 1.8;\">Sistem kuis interaktif mengevaluasi pilihan radio pengguna dan memberikan umpan balik langsung di layar.</p>\n</div>"
      },
      "vue_syllabus": {
